//class com.xq.GameInit
var GameInit=(function(){
	function GameInit(){
		this.isStarted=false;
		this.enterLabel=null;
	}

	__class(GameInit,'com.xq.GameInit');
	var __proto=GameInit.prototype;
	/**
	*启动开始
	**/
	__proto.onStart=function(){
		if(this.isStarted){
			return;
		}
		this.isStarted=true;
		Configs.initlauchParam();
		if(typeof(GameGlobal)!='undefined'){
			WXSDK.isInWX=GameGlobal.IS_IN_WEIXIN;
			fileVersion=GameGlobal.fileVersion;
			console.log(Lang.str(200)+fileVersion);
		}else{}
		if(typeof(Zlib)=='undefined'){
			AdaptConfig.ZlibEnabled=false;
			console.log(Lang.str(202));
			}else{
			console.log(Lang.str(203));
			AdaptConfig.ZlibEnabled=true;
		}
		Configs.init();
		CustomComponentInit.regComponents();
		CustomComponentInit.regAlert();
		Font.defaultSize=24;
		Font.defaultFamily="SimHei";
		Font.defaultFont="24px SimHei";
		Font.defaultColor="#d4e7f9";
		QGMiniAdapter.init();
		BMiniAdapter.init();
		KGMiniAdapter.init();
		QQMiniAdapter.init();
		if(WXSDK.isInWX){
			MiniAdpter.init();
			wx.showLoading({"title":Lang.str(204)});
			MiniAdpter.autoCacheFile=false;
			WXSDK.init();
		}
		Config.WebGLTextCacheCount=250;
		Laya.init(750 ,1334,WebGL);
		Configs.onLayaInited();
		LogLimitMgr.ins.setupRights();
		if(WXSDK.isInWX){
			Dialog.manager.yPadding=45;
			WXSDK.setPhonSys();
		}
		AtlasResourceManager.maxTextureCount=3;
		if(!Browser.onMiniGame)
			IPhoneXAdapt.ins.startCumctomAdapt();
		if(Browser.onMiniGame || Browser.onWeiXin){
			ResourceManager.systemResourceManager.autoRelease=false;
			ResourceManager.systemResourceManager.autoReleaseMaxSize=1024*1024*600;
			AmtLoaderMgr.instance.maxAtmMemorySize=1024*1024*450;
			AmtLoaderMgr.instance.maxMemorySize=1024*1024*550;
		}
		else if(Browser.onIOS){
			ResourceManager.systemResourceManager.autoRelease=false;
			ResourceManager.systemResourceManager.autoReleaseMaxSize=1024*1024*600;
			AmtLoaderMgr.instance.maxAtmMemorySize=1024*1024*450;
			AmtLoaderMgr.instance.maxMemorySize=1024*1024*550;
		}
		else if(Browser.onAndroid){
			ResourceManager.systemResourceManager.autoRelease=false;
			ResourceManager.systemResourceManager.autoReleaseMaxSize=1024*1024*600;
			AmtLoaderMgr.instance.maxAtmMemorySize=1024*1024*450;
			AmtLoaderMgr.instance.maxMemorySize=1024*1024*550;
		}
		else{
			ResourceManager.systemResourceManager.autoRelease=false;
			ResourceManager.systemResourceManager.autoReleaseMaxSize=1024*1024*600;
			AmtLoaderMgr.instance.maxAtmMemorySize=1024*1024*450;
			AmtLoaderMgr.instance.maxMemorySize=1024*1024*450;
		}
		AtlasResourceManager.atlasLimitHeight=256;
		AtlasResourceManager.atlasLimitWidth=256;
		if(Browser.onMiniGame){
			WorkerLoader.workerPath="worker/loader.js";
			WorkerLoader.enable=false;
		}
		else{
			WorkerLoader.workerPath="libs/worker.js";
		}
		try{
			if(LocalStorage.getItem("enableWorker")=="false" || Configs.isForbitWorker)
				WorkerLoader.enable=false;
			else
			WorkerLoader.enable=true;
		}
		catch(e){
			console.log(Lang.str(205));
			WorkerLoader.enable=false;
		}
		BaseSDK.changeFrameRate(false);
		console.log(Lang.str(206)+Render.isWebGL+":"+Laya.stage.width+"x"+Laya.stage.height);
		Laya.stage.alignH="center";
		Laya.stage.alignV="middle";
		Laya.stage.screenMode="none";
		if(Browser.onPC && !Render.isConchApp){
			if(Browser.clientWidth > 1024){
				Laya.stage.scaleMode="noscale";
			}
			else{
				Laya.stage.scaleMode="full";
			}
			Browser.window.onresize=this.onWindowResize;
			Laya.stage.scaleMode="fixedauto"
		}
		else{
			Laya.stage.scaleMode="fixedauto";
		}
		if(Render.isConchApp){
			PathDefine.getSoundUrl=PathDefine.getOGGSoundUrl;
		}
		PathDefine.initPath();
		var p={useragent:Browser.userAgent,stagewidth:Laya.stage.width,stageheight:Laya.stage.height};
		if(Render.is3DMode)
			p.rendermode="3D";
		else if(Render.isWebGL)
		p.rendermode="WEBGL";
		else
		p.rendermode="CANVAS";
		LogMgr.ins.startTime=Browser.now();
		LogMgr.ins.report(4,p);
		SoundManager.autoReleaseSound=false;
		var label=new Label(Lang.str(207));
		if(WXSDK.isInWX){
			label.visible=false;
		}
		label.x=(Laya.stage.width-120)*0.5;
		label.y=(Laya.stage.height-label.height)*0.5;;
		label.color="#ffffff";
		label.fontSize=20;
		this.enterLabel=label;
		var href=Browser.window.location.href;
		if(Browser.onMiniGame || Configs.isMiniGame){
			PathDefine.isPublish=true;
			URL.basePath=PathDefine.RES2_ROOT;
		}
		else if(href.indexOf("urlshare.cn")!=-1){
			PathDefine.isPublish=true;
			URL.basePath="https://tu86.cn/qzone_cdn/";
		}
		else if(href.indexOf(".com")!=-1
		|| href.indexOf(".cn")!=-1
		|| href.indexOf(".net")!=-1){
			PathDefine.isPublish=true;
			PathDefine.RES2_ROOT="";
		}
		else{
			PathDefine.isPublish=Configs.useFileVersionDic;
			if(PathDefine.isPublish){
				PathDefine.RES2_ROOT="";
			}
		}
		Configs.GM_OPEN=!PathDefine.isPublish;
		Configs.enableDBCache=PathDefine.isPublish;
		if(Configs.isForbitIndexDB)Configs.enableDBCache=false;
		Mgr.noticeMgr.init();
		CombineAni._basePath=PathDefine.ANI_PATH;
		if(Configs.holdVerticel){
			Laya.stage.screenMode="vertical";
		}
	}

	// Dialog.manager.closeEffectHandler=null;
	__proto.onWindowResize=function(){
		if(Browser.onPC){
			return;
		}
		if(Browser.height >=1000)
			Laya.stage.scaleMode="noscale";
		else
		Laya.stage.scaleMode="fixedauto";
	}

	// Laya.stage.scaleMode=Stage.SCALE_SHOWALL;
	__proto.onEnd=function(){
		this.enterLabel.removeSelf();
	}

	__getset(1,GameInit,'ins',function(){
		return GameInit._ins=GameInit._ins||new GameInit();
	});

	GameInit._ins=null;
	return GameInit;
})()


