//class com.xq.util.CommonAniTools
var CommonAniTools=(function(){
	function CommonAniTools(){}
	__class(CommonAniTools,'com.xq.util.CommonAniTools');
	CommonAniTools.disposeButtonAni=function(b){
		var childs=b._childs;
		var len=childs.length;
		for (var i=0;i < childs.length;i++){
			if (((childs[i])instanceof laya.xq.core.ani.UIAni )){
				var ani=childs[i];
				ani.dispose();
				ani=null;
			}
		}
	}

	CommonAniTools.addButtonAni=function(b){
		var childs=b._childs;
		var len=childs.length;
		var haveAni=false;
		for (var i=0;i < childs.length;i++){
			if (!haveAni && ((childs[i])instanceof laya.xq.core.ani.UIAni )){
				haveAni=true;
				break ;
			}
		}
		if (!haveAni){
			var ani=new UIAni;
			var url=PathDefine.OUT_RES+"ani/effect/ui/277saoguang.amt";
			ani.setRes(url);
			ani.pos(136,35);
			b.addChild(ani);
		}
	}

	CommonAniTools.addFlyAni=function(fromSp,endSp,effectType,duration,ease,delay,coverBefore,autoRecover){
		(duration===void 0)&& (duration=1000);
		(delay===void 0)&& (delay=0);
		(coverBefore===void 0)&& (coverBefore=false);
		(autoRecover===void 0)&& (autoRecover=true);
		var roll=100-Math.random()*200;
		var p0=new Point();
		p0.setTo(fromSp.x+roll,fromSp.y+roll);
		p0=(fromSp.parent).localToGlobal(p0);
		var p1=new Point();
		p1.setTo(endSp.x,endSp.y);
		p1=(endSp.parent).localToGlobal(p1);
		var effect=new Image();
		effect.skin=PathDefine.IMAGE+effectType;
		effect.x=p0.x;
		effect.y=p0.y;
		effect.zOrder=9999;
		Laya.stage.addChild(effect);
		Tween.to(effect,{x:p1.x,y:p1.y},duration,ease,Handler.create(null,CommonAniTools.complete,[effect]),delay,coverBefore,autoRecover);
	}

	CommonAniTools.complete=function(effect){
		effect.dispose();
		effect=null;
	}

	CommonAniTools.addSuccessAni=function(sp,url,x,y){
		(x===void 0)&& (x=5);
		(y===void 0)&& (y=5);
		if(!sp)
			return
		if (url==null){
			url=PathDefine.EQUIP_STREN_SUCCESS;
		};
		var successAni;
		if (sp["sucAni"]){
			successAni=sp["sucAni"];
			successAni.dispose();
			successAni=null;
		}
		if (!successAni){
			successAni=new UIAni();
		}
		successAni.setRes(url);
		successAni.loopTimes=1;
		successAni.pos(x,y);
		sp.addChild(successAni);
		sp["sucAni"]=successAni;
	}

	CommonAniTools.LIGHT_POINT="juqing/hongdian.png";
	return CommonAniTools;
})()


