//class com.xq.util.RequestLimit
var RequestLimit=(function(){
	function RequestLimit(){}
	__class(RequestLimit,'com.xq.util.RequestLimit');
	__getset(1,RequestLimit,'dic',function(){
		return RequestLimit._dic=RequestLimit._dic|| new Dictionary();
	});

	RequestLimit.check=function(o,time){
		(time===void 0)&& (time=500);
		var t=RequestLimit.dic[o];
		if(t==null){
			RequestLimit.dic[o]=time+Browser.now();
			return true;
		};
		var i=t-Browser.now();
		if(i > 0){
			return false;
		}
		RequestLimit.dic[o]=time+Browser.now();
		return true;
	}

	RequestLimit._dic=null;
	return RequestLimit;
})()


