//class view.modules.common.LoadingUtil
var LoadingUtil=(function(){
	function LoadingUtil(){}
	__class(LoadingUtil,'view.modules.common.LoadingUtil');
	LoadingUtil.showLoading=function(type){
		(type===void 0)&& (type=1);
		switch(type){
			case 0:
				LoadingUtil.showJuHua();
				break ;
			case 1:
				LoadingUtil.showForce();
				break ;
			}
	}

	LoadingUtil.hideLoading=function(type){
		(type===void 0)&& (type=1);
		switch(type){
			case 0:
				LoadingUtil.hideJuHua();
				break ;
			case 1:
				LoadingUtil.hideForce();
				break ;
			}
	}

	LoadingUtil.showForce=function(){
		Laya.timer.frameOnce(2,LoadingUtil,view.modules.common.LoadingUtil.laterShowForce);
	}

	LoadingUtil.laterShowForce=function(){
		if(!LoadingUtil.force){
			LoadingUtil.yabai=new Sprite();
			LoadingUtil.yabai.zOrder=99998;
			LoadingUtil.force=new UIAni();
			LoadingUtil.force.zOrder=99998;
			LoadingUtil.force.x=Laya.stage.width >>1;
			LoadingUtil.force.y=Laya.stage.height >> 1;
		}
		LoadingUtil.force.setRes(PathDefine.getUIEffectUrl("Loading02"));
		LoadingUtil.yabai.graphics.clear();
		LoadingUtil.yabai.width=Laya.stage.width;
		LoadingUtil.yabai.height=Laya.stage.height;
		LoadingUtil.yabai.alpha=0.2;
		Laya.stage.addChild(LoadingUtil.yabai);
		Laya.stage.addChild(LoadingUtil.force);
	}

	LoadingUtil.hideForce=function(){
		Laya.timer.clear(LoadingUtil,view.modules.common.LoadingUtil.laterShowForce);
		if(LoadingUtil.yabai){
			LoadingUtil.force.recover();
			LoadingUtil.yabai.removeSelf();
			LoadingUtil.force.removeSelf();
			LoadingUtil.yabai.graphics.clear();
		}
	}

	LoadingUtil.showJuHua=function(){
		if(!LoadingUtil.loadImage){
			LoadingUtil.loadImage=new Image();
			LoadingUtil.loadImage.pivotX=40;
			LoadingUtil.loadImage.pivotY=40;
			LoadingUtil.loadImage.centerX=0;
			LoadingUtil.loadImage.centerY=-40+Dialog.manager.yPadding;
			LoadingUtil.loadImage.zOrder=10000;
			LoadingUtil.loadImage.skin=PathDefine.IMAGE+"loading"+".png";
		}
		Laya.stage.addChild(LoadingUtil.loadImage);
		Laya.timer.frameLoop(1,LoadingUtil,LoadingUtil.loading);
	}

	LoadingUtil.loading=function(){
		LoadingUtil.loadImage.rotation+=3;
	}

	LoadingUtil.hideJuHua=function(){
		if(LoadingUtil.loadImage)
			LoadingUtil.loadImage.removeSelf();
		Laya.timer.clear(LoadingUtil,LoadingUtil.loading);
	}

	LoadingUtil.JU_HUA=0;
	LoadingUtil.XIAO_HEI_MA=1;
	LoadingUtil.force=null;
	LoadingUtil.yabai=null;
	LoadingUtil.loadImage=null;
	return LoadingUtil;
})()


