	/**
	*uimgr打开面板
	*@param viewClass 模块名
	*@param level 面板级别，便于管理，默认一级面板,暂时只存储1,2级面板
	*@param index Tab的index,-1表示没有tab
	*@param closeOther 只针对1级面板起作用，隐藏某些面板或单位：1：隐藏主界面；2：隐藏主界面+场景上的所有单位
	*@param autoShow 自动添加到舞台或者弹出
	**/
	__proto.openView=function(viewClass,level,index,closeOther,autoShow,callBack){
		(level===void 0)&& (level=1);
		(index===void 0)&& (index=-1);
		(closeOther===void 0)&& (closeOther=0);
		(autoShow===void 0)&& (autoShow=true);
		EventCenter.instance.event(GameEvent.Close_All_QiPao);
		this._secTabIndex=-1;
		this._thirdTabIndex=-1;
		if(this.loadingDic[viewClass]){
			return this.uiClassDic[viewClass];
		}
		this.loadingDic[viewClass]=true;
		if(index!=-1){
			this.tabIdxDic[viewClass]=index;
		};
		var curView=this.uiClassDic[viewClass];
		if(curView==null){
			curView=new viewClass();
			this.uiClassDic[viewClass]=curView;
			curView.on("open",this,this.checkAndOpTabN,[curView,viewClass.name]);
		}
		if(curView.hasOwnProperty("checkCanOpen")){
			if(!curView["checkCanOpen"]()){
				return this.uiClassDic[viewClass];
			}
		}
		LoadingUtil.showLoading(1);
		var onLoaded=Handler.create(this ,this._openView ,[viewClass,level,index,-1,-1,closeOther,autoShow,callBack] ,false);
		this.uiResMgr.loadUIRes(viewClass,onLoaded);
		if(!PathDefine.isPublish && curView.name){
			console.log(Lang.str(1903)+curView.name+Lang.str(1904));
		}
		return this.uiClassDic[viewClass];
	}

