	__proto._checkUpdateSkin=function(viewClass){
		if(this.uiResMgr.isLoadOnDemand(viewClass)){
			var skinComps=this.skinComponentDic[viewClass];
			if(skinComps==null){
				skinComps={};
				skinComps["skin"]=[];
				skinComps["labelSkin"]=[];
				skinComps["list"]=[];
				this.skinComponentDic[viewClass]=skinComps;
				var uiView=this.uiClassDic[viewClass];
				if(uiView==null){
					uiView=new viewClass();
					this.uiClassDic[viewClass]=uiView;
				}
				this._searchSkinElement(uiView,skinComps["skin"],skinComps["labelSkin"],skinComps["list"]);
				Laya.timer.frameOnce(1,this,this.laterupskin,[skinComps],false);
			}
			else{
				this.laterupskin(skinComps);
			}
		}
	}

	__proto.laterupskin=function(skinComps){
		var skins=skinComps.skin;
		var skinItem;
		for(var $each_skinItem in skins){
			skinItem=skins[$each_skinItem];
			var pre=skinItem.skin;
			if(skinItem.parent && pre){
				skinItem.skin="";
				skinItem.skin=pre;
			}
		};
		var labelSkins=skinComps.labelSkin;
		var labelSkinItem;
		for(var $each_labelSkinItem in labelSkins){
			labelSkinItem=labelSkins[$each_labelSkinItem];
			var pre1=labelSkinItem.labelSkin;
			if(pre1){
				labelSkinItem.labelSkin="";
				labelSkinItem.labelSkin=pre1;
			}
		};
		var lists=skinComps.list;
		var listItem;
		for(var $each_listItem in lists){
			listItem=lists[$each_listItem];
			var cells=listItem.cells;
			var len=cells.length;
			for (var i=0;i < len;i++){
				this._refreshList(cells[i]);
			}
		}
	}

	__proto._refreshList=function(comp){
		var clidrens=comp._childs;
		var len=clidrens.length;
		for (var i=0;i < len;i++){
			var node=clidrens[i];
			this._refreshList(node);
		}
		if(comp.hasOwnProperty("skin")){
			var pre=comp["skin"];
			if(pre){
				comp["skin"]="";
				comp["skin"]=pre;
			}
		}
	}

	__proto._searchSkinElement=function(comp,skinItems,labelSkinItems,lists){
		var clidrens=comp._childs;
		var len=clidrens.length;
		for (var i=0;i < len;i++){
			var node=clidrens[i];
			this._searchSkinElement(node,skinItems ,labelSkinItems ,lists);
		}
		if(comp.hasOwnProperty("labelSkin")){
			labelSkinItems.push(comp);
		}
		if(comp.hasOwnProperty("skin")){
			skinItems.push(comp);
		}
		else if((comp instanceof laya.ui.List )){
			lists.push(comp);
		}
	}

	__proto._openView=function(viewClass,level,index,index2,index3,closeOther,autoShow,callBack){
		(level===void 0)&& (level=1);
		(index===void 0)&& (index=-1);
		(index2===void 0)&& (index2=-1);
		(index3===void 0)&& (index3=-1);
		(closeOther===void 0)&& (closeOther=0);
		(autoShow===void 0)&& (autoShow=false);
		delete this.loadingDic[viewClass];
		LoadingUtil.hideLoading(1);
		var curView=this.uiClassDic[viewClass];
		if(curView==null){
			curView=new viewClass();
			this.uiClassDic[viewClass]=curView;
		}
		this.digObj.set(curView,viewClass);
		if(level==1){
			if(curView && this.curClass !=viewClass){
				this.closeAllPanelBylv(-2,false,curView);
			}
		}
		this.curClass=viewClass;
		if(level==1){
			if((curView instanceof laya.ui.Dialog ))
				this.curDia=curView
			this.model._1stViewDic[viewClass]=curView;
		}
		else if (level==2){
			this.model._2ndViewDic[viewClass]=curView;
		}
		else if(level==3){
			this.model._3ndViewDic[viewClass]=curView;
		}
		if((curView instanceof laya.ui.FrameView )){
			this.showPanelOnFrameWork(viewClass,curView);
		}
		else if((curView instanceof laya.ui.Dialog )){
			if(!(curView).isPopup){
				if(autoShow)
					(curView).popup();
				else
				(curView).show();
			}
			if(this.dialogDic[viewClass]){
				Game.getInstance().uiLayerBottom.addChild(curView);
			}
		}
		else if((curView instanceof laya.ui.View )){
			if(curView.hasOwnProperty("onOpened")){
				curView["onOpened"]();
			}
			Game.getInstance().uiLayerBottom.addChild(curView);
		}
		curView.event("open");
		if(index !=-1 || this.tabIdxDic[viewClass]!=null){
			this._secTabIndex=index2;
			this._thirdTabIndex=index3;
			var idx=this.tabIdxDic[viewClass]==null? index :this.tabIdxDic[viewClass];
			Laya.timer.callLater(this,this.delayOnceChoose,[curView,idx,callBack,viewClass]);
			delete this.tabIdxDic[viewClass];
		}
		if(index !=-1){
			if(curView["menuList"])
				curView["menuList"].selectedIndex=index;
		}
		else{
			if(callBack){
				callBack.run();
			}
			EventCenter.instance.event("OPENVIEW",[this.classNameDic[viewClass],curView]);
			curView.event("OPENVIEW");
		}
		Laya.timer.frameOnce(1,this,this._checkUpdateSkin,[viewClass],false);
		return curView;
	}

	__proto.showPanelOnFrameWork=function(viewClas,view){
		if(!this.frameGroup.displayedInStage){
			this.frameGroup.zOrder=100;
			Game.getInstance().uiLayer.addChild(this.frameGroup);
		}
		this.frameGroup.setContentView(viewClas,view);
	}

	__proto.delayOnceChoose=function(curView,index,callBack,viewClass){
		if(curView["naviTab"])
			curView["naviTab"].selectedIndex=index;
		else if(curView["tab_tab"])
		curView["tab_tab"].selectedIndex=index;
		if(callBack){
			callBack.run();
		}
		EventCenter.instance.event("OPENVIEW",this.classNameDic[viewClass]);
		curView.event("OPENVIEW");
	}

	/**关闭框架面板*/
