	/**
	*关闭某一级别的所有面板
	*@param lv 级别面板，默认-1 关闭所有打开面板(除了3级面板)-2关闭所有继承FrameView面板
	*/
	__proto.closeAllPanelBylv=function(Lv,has3,spV){
		(Lv===void 0)&& (Lv=-1);
		(has3===void 0)&& (has3=false);
		if(Lv==1 || Lv < 0){
			var obj=this.model._1stViewDic;
			var v;
			for(var $each_v in obj){
				v=obj[$each_v];
				if(spV && spV==v){
					continue ;
				}
				if(v){
					this.closePanel(v);
				}
			}
			this.model._1stViewDic=new Object();
		}
		if(Lv==2 || Lv < 0){
			var obj2=this.model._2ndViewDic;
			for (v in obj2){
				var tempV=obj2[v];
				if(tempV){
					if(spV && spV==tempV){
						continue ;
					}
					if((tempV instanceof laya.ui.FrameView )|| Lv !=-2){
						this.closePanel(tempV);
						delete obj2[v]
					}
				}
			}
			if(Lv==2){
				this.model._2ndViewDic=new Object();
			}
		}
		if(has3){
			var obj3=this.model._3ndViewDic;
			var $each_v;
			for($each_v in obj3){
				v=obj3[$each_v];
				if(v)
					this.closePanel(v);
			}
			this.model._3ndViewDic=new Object();
		}
	}

	__proto.closePanel=function(view){
		if(!view){
			return;
		}
		if((view instanceof laya.ui.Dialog )){
			if((view).isPopup){
				(view).close();
			}
		}
		else if((view instanceof laya.ui.FrameView )){
			(view).close2();
		}
		else if((view instanceof laya.ui.View )){
			if((view).hasOwnProperty("close"))
				view["close"]();
			(view).removeSelf();
		}
	}

	/**剧情模式用到消失所有的面板*/
	__proto.hideAll=function(){
		Game.getInstance().getNewMainView().visible=false;
		Game.getInstance().actBar.visible=false;
		this.frameGroup.visible=false;
		if(this.curClass){
			var v1=this.uiClassDic[this.curClass];
			if(v1.visible){
				this.flagArr.push(v1);
				v1.visible=false;
			}
		};
		var obj=this.model._2ndViewDic;
		var v;
		for(var $each_v in obj){
			v=obj[$each_v];
			if(v.visible){
				this.flagArr.push(v);
				v.visible=false;
			}
		}
		obj=this.model._3ndViewDic;
		var $each_v;
		for($each_v in obj){
			v=obj[$each_v];
			if(v.visible){
				this.flagArr.push(v);
				v.visible=false;
			}
		}
		Game.getInstance().uiLayer.visible=false;
		MainEffectViewUtil.mainEffctView.visible=false;
		MainQiPaoViewUtil.mainQiPaoView.visible=false;
		Dialog.manager.maskLayer.visible=false;
	}

	/**剧情模式用到的 显示之间消失的面板*/
	__proto.showAll=function(){
		Game.getInstance().actBar.visible=true;
		Game.getInstance().getNewMainView().visible=true;
		this.frameGroup.visible=true;
		if(this.flagArr){
			var len=this.flagArr.length;
			for(var i=0;i<len;i++){
				this.flagArr[i].visible=true;
			}
			this.flagArr.length=0;
		}
		Dialog.manager.maskLayer.visible=true;
		MainEffectViewUtil.mainEffctView.visible=true;
		MainQiPaoViewUtil.mainQiPaoView.visible=true;
		Game.getInstance().uiLayer.visible=true;
	}

	/**
	*通过功能ID打开对应的面板。必须在uiControl中存在
	*@param funID 对应的FunctionDefine中的ID
	**/
	__proto.openViewByFunID=function(funID,callback,uiLv){
		(uiLv===void 0)&& (uiLv=1);
		var id=this.panelIDObj[funID];
		if(!id){
			var obj=this.getUiCfgByFunId(funID);
			if(obj){
				id=obj.ID;
				this.panelIDObj[funID]=id;
			}
			else{
				console.log(Lang.str(1908)+funID);
			}
		}
		if(id > 0){
			this.navigateToViewByID(id,callback,uiLv,"");
		}
	}

	/**
	*通过uicontrol表的ID打开对应面板
	*@param _openMatId 同过这种ID打开的面板
	**/
	__proto.navigateToViewByID=function(operateID,callBack,uiLv,_openMatId){
		(uiLv===void 0)&& (uiLv=2);
		(_openMatId===void 0)&& (_openMatId="");
		if(Configs.isForbitIOSPay||Configs.isForbitAndroidPay){
			if(this.forbitOpenList.indexOf(operateID)>=0){
				return false;
			}
		}
		if(operateID==99999){
			if(!ZhuChengMgr.ins.isZhuCheng){
				EventCenter.instance.event("skip_zhucheng");
				view.UIMgr.ins.closeAllPanelBylv();
				}else{
				Mgr.prompt.optionPrompt(Lang.str(1909));
			}
			return false;
		}
		if(operateID==100004 && !Mgr.userLogin.canPay){
			return false;
		}
		if(operateID==1){
			Mgr.prompt.optionPrompt(Lang.str(1656));
			return false;
		}
		else if(operateID==70270 || operateID==70271 || operateID==70272){
			Mgr.prompt.optionPrompt(Lang.str(1910));
			return false;
		};
		var item=this.uiControlTable.getItemByField("ID",operateID);
		if (!item){
			console.log(Lang.str(1911)+operateID+Lang.str(1912));
			return false;
		};
		var func=item.funcId;
		var isOpen=Mgr.guide.isOpen(item.parentFunc,true);
		if(!isOpen){
			return false;
		};
		var isOpen2=Mgr.guide.isOpen(func,true);
		if (isOpen && isOpen2){
			this._materialId=_openMatId;
			if(func=="zongmen"){
				if(operateID==7003 || operateID==7006 || operateID==7005){
					if(NetMgr.ins().roleVO.guildId <=0){
						Mgr.prompt.optionPrompt(Lang.str(1913));
						return false
					}
				}
			};
			var isOk=false;
			if(item.main=="Action"){
				Mgr.uiAct.doAction(parseInt(item.tab));
				isOk=true;
			}
			else{
				var ip=Mgr.guide.checkActIsOp(func);
				if(!ip){
					Mgr.prompt.optionPrompt(Lang.str(888));
				}
				if(item.parentTab){
					var tabAry=item.parentTab.split(":");
					var main=tabAry[0];
					var pIndex=parseInt(tabAry[1]);
					var tabView=this.uiNameDic[tabAry[0]];
					var pItem=this.uiControlTable.getCfgMsgByTwoKey("main",main,"tab",pIndex);
					if(pItem){
						var gFunc=pItem.parentTab;
						if(gFunc){
							var gTabArr=gFunc.split(":");
							var gTabMain=gTabArr[0];
							var gTabIndex=gTabArr[1];
							var gItem=this.uiControlTable.getCfgMsgByTwoKey("main",gTabMain,"tab",gTabIndex);
						}
					}
					if(!gItem||!this.uiNameDic[gItem.main]){
						this.openSecView(tabView ,uiLv ,parseInt(tabAry[1]),parseInt(item.tab),0,true ,callBack);
					}
					else{
						var gMain=gItem.main;
						var gIndex=parseInt(gItem.tab);
						this.openThirdView(this.uiNameDic[gMain],uiLv ,gIndex,parseInt(tabAry[1]),parseInt(item.tab),0,true ,callBack);
					}
				}
				else{
					var clas=this.uiNameDic[item.main];
					if(clas){
						if(this.behindShouChongClass[clas] && Mgr.kaiFuHDMgr.progress==0){
							view.UIMgr.ins.openView(ShouChongHaoLiView,1);
						}
						else if(!item.className){
							this.openViewForListPanel(clas,uiLv,item.tab);
						}
						else{
							this.openView(clas ,uiLv ,parseInt(item.tab),0,true ,callBack);
						}
					}
				}
			}
			if(isOk){
				if(callBack){
					callBack.run();
				}
			}
		}
		else{
			return false;
		}
		return true
	}

