//class view.mainUI.subPanel.chatPanel.ChatRenderView extends laya.ui.View
var ChatRenderView=(function(_super){
	function ChatRenderView(){
		/**最大宽度*/
		this._maxWidth=295;
		this.paramas3=null;
		this.html=null;
		this.renderCompelte=null;
		this.cd=true;
		ChatRenderView.__super.call(this);
	}

	__class(ChatRenderView,'view.mainUI.subPanel.chatPanel.ChatRenderView',_super);
	var __proto=ChatRenderView.prototype;
	__proto.initialize=function(){
		this.setupHtml();
		this.on("click",this,this.onlink,[false]);
	}

	__proto.setupHtml=function(){
		this.html=new HtmlDivElement();
		this.html.pos(0,0);
		this.html.width=this._maxWidth;
		this.html.imgOffY=-2;
		this.html.fontSize=18;
		this.html.renderCompleteHandler=Handler.create(this,this.renderOk,null,false);
		this.addChild(this.html);
	}

	__proto.renderOk=function(){
		this.visible=true;
		this.height=this.html.contextHeight;
		this.width=this.html.contextWidth;
		if(this.renderCompelte){
			this.renderCompelte.run();
			this.renderCompelte=null;
		}
	}

	__proto.onlink=function(data){
		if(!this.cd)
			return;
		if(data==false){
			UIMgr.ins.openView(ChatPanelView,1);
			return;
		}
		this.cd=false;
		Laya.timer.once(100,this,this.resetcd);
		var panelid=parseInt(data);
		if(panelid){
			if(this.paramas3){
				Mgr.guide.sencondeTip(this.paramas3.funid,this.paramas3.data,this.paramas3.type);
			}
			else{
				UIMgr.ins.navigateToViewByID(panelid);
				UIMgr.ins.closeView(ChatPanelView);
			}
		}
		else{
			if(data["templateId"]){
				data.whichPanel=10;
				Mgr.item.openTip(data.templateId);
			}
			else if(data["mapid"]){
				AIController.ins().startAutoPath(data.mapid,data.x,data.y);
			}
		}
	}

	__proto.resetcd=function(){
		this.cd=true;
	}

	__proto.setType=function(type){
		var h=19;
		var w=39;
		var url=PathDefine.CHAT+type+".png";
		var imgs="<img width='"+w+"' height='"+h+"' src='"+url+"'/>"+"&nbsp;";
		return imgs;
	}

	__proto.dispose=function(){
		this.removeSelf();
		this.renderCompelte=null;
		this.offAll();
		view.mainUI.subPanel.chatPanel.ChatRenderView.recover(this);
	}

	__getset(0,__proto,'htmlWidth',null,function(width){
		this.html.width=width;
	});

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		this.html.offAll();
		this.visible=false;
		this._dataSource=value;
		var imgStr=this.setType(value.chatType);
		if(!value.name || !value.guid){
			var msg="";
		}
		else{
			msg="<font color='#77f440'>"+value.name+":</font>";
		};
		var parserMsg;
		if(value.params1 && value.params1!=""){
			var itemVo=JSON.parse(value.params1);
			parserMsg=MessageParserMgr.ins.parser1(value.message,itemVo);
			this.html.on("click",this,this.onlink,[itemVo]);
		}
		else{
			parserMsg=MessageParserMgr.ins.parser(value.message);
			if(parserMsg.indexOf("$c")!=-1){
				var m=value.message;
				m=m.replace("$c","");
				parserMsg=CodeMgr.ins.getStringByCode(m);
			}
		}
		this.paramas3=null;
		if(value.params3 && value.params3!=""){
			var data=JSON.parse(value.params3);
			this.paramas3=data;
		}
		if(parserMsg &&parserMsg.indexOf("href")!=-1){
			this.html.on("link",this,this.onlink);
		}
		if(parserMsg){
			this.html.innerHTML=imgStr+msg+parserMsg;
		}
		else{
			this.html.innerHTML=imgStr+msg
		}
	});

	ChatRenderView.getItem=function(){
		return Pool.getItemByClass("ChatRenderView",ChatRenderView);
	}

	ChatRenderView.recover=function(item){
		Pool.recover("ChatRenderView",item);
	}

	return ChatRenderView;
})(View)


