		this.curH=0;
		this.cahAry=[];
		if(FunDebug.debug_mem.length >=50){
			var index=FunDebug.debug_mem.length-50;
			FunDebug.debug_mem.splice(0,index);
		};
		var len=FunDebug.debug_mem.length;
		for (var i=0;i < len;i++){
			this.curIndex++;
			this.showItem(FunDebug.debug_mem[i]);
		}
