	__proto.changeCeng=function(cengNum){
		if(this.lastCeng>cengNum){
			this.txt_ceng.value="x"+(this.lastCeng-1);
			this.lastCeng--;
			Laya.timer.frameOnce(2,this,this.changeCeng,[cengNum]);
		}
	}

	/**更新血条*/
	__proto.updateBlood=function(per){
		if(this.cd > Browser.now()&& per >0.3){
			return;
		}
		this.cd=Browser.now()+1000;
		if(this.mc_boss.visible){
			if(this.mulblood){
				var strCurHp=CommonUtil.numFormat2(this.mvo.curHp);
				var strMaxHp=CommonUtil.numFormat2(this.mvo.maxHp);
				this.txt_per.changeText(strCurHp+"/"+strMaxHp);
				this.mulblood.updateBlood(per);
				this.changeCeng(this.mulblood.cengNum);
			}
		}
		else{
			if(this.baseblood)
				this.baseblood.updateBlood(per);
		}
		if(per <=0){
			this.gc();
			return;
		}
	}

	__proto.showBossWudi=function(){
		if(this.curUnit && (this.curUnit instanceof com.xq.rpg.unit.Monster )){
			var vo=this.curUnit.vo;
			var wudiEndTime=vo.wudiEndTime;
			var chixuTime=vo.wudiChiXuTime;
			if(wudiEndTime > Mgr.curTime.serverTimer){
				this.img_wudi.visible=true;
				this.txt_name.color="#ff4141";
				this.showBossWudiDjs(wudiEndTime,chixuTime);
				Laya.timer.loop(100,this,this.showBossWudiDjs,[wudiEndTime,chixuTime]);
				}else{
				this.img_wudi.visible=false;
				this.txt_name.color="#d4e7f9";
				var monsterId=this.mvo.monsterId;
				var cof=Model.monster.getMonsterCfgById(monsterId);
				if(cof){
					this.txt_name.text=cof.name;
				}
				this.hbox.refresh();
			}
		}
	}

	__proto.showBossWudiDjs=function(endTime,chixuTime){
		var serTime=Mgr.curTime.serverTimer;
		if(endTime < serTime){
			Laya.timer.clear(this,this.showBossWudiDjs);
			this.showBossWudi();
			return;
		};
		var remainTime=endTime-serTime;
		this.img_wudi.width=(remainTime/chixuTime)*348;
		this.txt_name.color="#ffd951";
		this.txt_name.text=Lang.str(354);
		this.hbox.refresh();
	}

	__proto.onClickHead=function(){}
	//有 需要显示的再显示 不需要显示的就不显示 根据BossOwnerItemShowType来
	__proto.setOwer=function(vo,BossOwnerItemShowType){
		(BossOwnerItemShowType===void 0)&& (BossOwnerItemShowType=0);
		if(!this.mvo)return;
		if(!vo){
			this.BossOwner.visible=false;
			return;
		}
		if(vo.monsterId !=this.mvo.guid)return;
		if(vo.ownerId==0||BossOwnerItemShowType==0){
			this.BossOwner.visible=false;
			return;
		}
		this.BossOwner.visible=true;
		vo["showType"]=BossOwnerItemShowType;
		this.rankList.array=[vo];
	}

