var TopHeroCardView=(function(_super){
	function TopHeroCardView(){
		this.subplayerVo=null;
		this.timeLabel=null;
		this.isReviving=false;
		TopHeroCardView.__super.call(this);
	}

	__class(TopHeroCardView,'view.mainUI.subPanel.TopHeroCardView',_super);
	var __proto=TopHeroCardView.prototype;
	__proto.onExitScene=function(){
		if(this.isReviving){
			this.stopReviveTick(false);
		}
	}

	__proto.stopReviveTick=function(sendMsg){
		this.isReviving=false;
		this.timeLabel.removeSelf();
		this.timeLabel=null;
		Laya.timer.clear(this,this.onTick);
		this.imgHead.gray=false;
		if(sendMsg && this.subplayerVo){
			Mgr.skillPro.sendSubRoleRevive(this.subplayerVo.roleId)
		}
	}

	__proto.onRoleDead=function(unit){
		if(this.subplayerVo && this.subplayerVo.roleId==unit.guid){
			var sec=Mgr.cfgMgr.getValueByType(165);
			this.subplayerVo.reviveTime=Browser.now()+sec*1000;
			this.startReviveTick();
		}
	}

	__proto.startReviveTick=function(){
		this.isReviving=true;
		this.imgHead.gray=true;
		this.timeLabel=new Text();
		this.timeLabel.x=0;
		this.timeLabel.y=26;
		this.timeLabel.align="center";
		this.timeLabel.width=70;
		this.timeLabel.color="#4dff55";
		this.timeLabel.fontSize=30;
		this.addChild(this.timeLabel);
		Laya.timer.loop(1000,this,this.onTick);
	}

	__proto.onTick=function(){
		var now=Browser.now();
		var leftTime=this.subplayerVo.reviveTime-now;
		if(leftTime>0){
			this.timeLabel.changeText(Math.round(leftTime/1000)+"");
		}
		else{
			this.stopReviveTick(true);
		}
	}

	// ani.visible=false;
	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		Laya.superSet(TopPanelHeroCardUI,this,'dataSource',value);
		if(!value)
			return
		this.imgHead.visible=false;
		this.subplayerVo=value;
		if(this.subplayerVo){
			var id=this.subplayerVo.shenJiangType;
			if(id > 0){
				if(this.subplayerVo.shenJiangType > Mgr.heroSysMgr.heroModel.minGap){
					var sjCfg=Mgr.szMgr.getCfgById(this.subplayerVo.shenJiangType+"");
				}
				else{
					sjCfg=Mgr.heroSysMgr.getSjCfg(this.subplayerVo.shenJiangType);
				}
				this.imgHead.visible=true;
				this.imgHead.skin=PathDefine.getShenJiangHeadUrl(sjCfg.icon);
				this.imgHead.pos(0,0);
				this.imgHead.scale(1,1);
				EventCenter.instance.on("role_dead_event",this,this.onRoleDead);
				EventCenter.instance.on("EXIT_SCENE" ,this ,this.onExitScene);
			}
		}
	});

	return TopHeroCardView;
})(TopPanelHeroCardUI)


