var SuperSkillItem=(function(_super){
	function SuperSkillItem(){
		this._mgr=null;
		/**类型*/
		this._vo=null;
		/**就绪动画*/
		this._readyAni=null;
		/**当前的状态*/
		this._stat=0;
		this._skill="";
		/**抖动动画*/
		this._shake=null;
		this._ifHideName=false;
		SuperSkillItem.__super.call(this);
		this._mgr=Mgr.actionSkillM;
		this.startListener();
	}

	__class(SuperSkillItem,'view.mainUI.SuperSkillItem',_super);
	var __proto=SuperSkillItem.prototype;
	__proto.startListener=function(){
		this.img_skillicon.on("click",this,this.onUseSkill);
	}

	__proto.update=function(data){
		if(!data)return;
		this._vo=data;
		this.updateReadyAni();
		if(!this._ifHideName){
			this.img_name.skin=PathDefine.getActionSkillTypeName(this._vo.slot);
		};
		var ifOpen=data.stat>1;
		this.img_lock.visible=!ifOpen;
		if(!this.img_lock.skin)this.img_lock.skin=PathDefine.getCommonRes("lock2");
		this.updateSkill(data.skill)
		this.updateStat(this._vo.stat);
	}

	__proto.updateReadyAni=function(){
		if(!this._readyAni){
			this._readyAni=new UIAni();
			this.sp_ani.addChild(this._readyAni);
			this._readyAni.setRes(PathDefine.getUIEffectUrl("skill_kp1"));
			this._readyAni.scale(0.5,0.5);
			this._readyAni.mouseThrough=true;
			this._readyAni.visible=false;
		}
	}

	/**更新技能 图标*/
	__proto.updateSkill=function(skill){
		if(_skill==skill)return;
		_skill=skill;
		if(this._vo.heJiType=="BIANSHEN"){
			var _skill=this._mgr.getTianShenSkill();
			var vo=SkillManager.ins.getData(_skill);
			if(!vo)return;
			var iconUrl=vo.iconUrl;
			var url=PathDefine.getHejiSkillIcon(iconUrl);
		}
		else{
			var iconId=Model.heji.getHeJiIcon(_skill);
			if(!iconId)iconId="heji00";
			url=PathDefine.getHejiSkillIcon(iconId);
		}
		this.img_skillicon.skin=url;
	}

	/**播放解锁动画*/
	__proto.playUnlockAni=function(){
		this._shake=ShakeTween.START(this.img_lock,90,50,10,2);
		Tween.to(this.img_lock,{alpha:0},300,null,Handler.create(this,this.hideLock),500);
	}

	__proto.hideLock=function(){
		if(this._shake)
			this._shake.stop();
		Tween.clearTween(this.img_lock);
	}

	__proto.updateStat=function(curStat){
		if(this._stat==3){
			var time=((this._vo.readyTime-Browser.now())/1000);
			var timestr=time<=0?"":time.toFixed();
			this.txt_cd.changeText(timestr);
		}
		if(this._stat==curStat)return;
		this._stat=curStat;
		this.img_lock.visible=this._stat==1;
		this.img_skillicon.visible=this._stat>2;
		this.img_skillicon.gray=this._stat==3;
		this._readyAni.visible=this._stat==4;
		this.txt_cd.visible=this._stat==3;
	}

	__proto.onUseSkill=function(){
		var ifSuccess=Mgr.actionSkillM.useSuperSkillByVo(this._vo);
		if(ifSuccess){
			this.playUseAni();
		}
	}

	//后面提出来
	__proto.playUseAni=function(){
		this.img_ani.visible=true;
		var startX=this.img_skillicon.x;
		var startY=this.img_skillicon.y;
		this.img_ani.pos(startX,startY);
		this.img_ani.alpha=1;
		this.img_ani.scale(1,1);
		Tween.clearAll(this.img_ani);
		Tween.to(this.img_ani,{alpha:0.7,x:startX+350,y:startY-400},600,Ease.circInOut);
		Tween.to(this.img_ani,{alpha:0,scaleX:20,scaleY:20},500,Ease.circInOut,Handler.create(this,this.disappearAniImage),600);
		Laya.timer.once(1500,this,this.disappearAniImage);
	}

	__proto.disappearAniImage=function(){
		Laya.scaleTimer.clear(this,this.disappearAniImage);
		this.img_ani.visible=false;
	}

	__proto.hideName=function(){
		this._ifHideName=true;
		this.img_name.visible=false;
	}

	return SuperSkillItem;
})(SuperSkillItemUI)


