var JXLItemView=(function(_super){
	function JXLItemView(){
		JXLItemView.__super.call(this);
	}

	__class(JXLItemView,'view.modules.barrier.JXLItemView',_super);
	var __proto=JXLItemView.prototype;
	__proto.initData=function(index,curCardId){
		(curCardId===void 0)&& (curCardId=0);
		var gqMgr=Mgr.gqMgr;
		curCardId=curCardId==0?gqMgr.curCardId:curCardId;
		var cardId=curCardId;
		var obj=gqMgr.getCardCfg(cardId);
		var guanka=obj.guanqia.split(";");
		var cardMsg=gqMgr.getCardMsgById(cardId);
		var nextLevel=gqMgr.gqInfo.nextLevel-1;
		var mubiao=guanka[index-1];
		this.img_font.skin=PathDefine.ShenJiangCardImg+"img_name/"+index+".png";
		this.img_font.gray=true;
		if(nextLevel < mubiao){
			this.box_desc.visible=true;
			this.txt_desc.text=Lang.str(476)+mubiao+Lang.str(3335);
			}else{
			this.box_desc.visible=false;
			if(cardMsg && index <=cardMsg.progress){
				this.img_font.gray=false;
			}
		}
	}

	__proto.playBoomAni=function(){
		CommonAniTools.addSuccessAni(this.img_font,null,0,0);
		Laya.timer.once(150,this,this.grayChange,[false]);
	}

	__proto.grayChange=function(bo){
		this.img_font.gray=false;
	}

	__proto.dispose=function(){
		this.img_font.skin="";
	}

	return JXLItemView;
})(JXLItemUI)


