//class view.modules.bossHall.sanjieBoss.BossHarmReward extends ui.modules.bossHall.sanjieBoss.BossHarmRewardUI
var BossHarmReward=(function(_super){
	function BossHarmReward(){
		this.monsterId=null;
		this.myHarmValue=0;
		this.nextTargetHarmValue=0;
		this.rewardItems=null;
		this.hasReward=false;
		this.curRewardId=0;
		this._ani=null;
		BossHarmReward.__super.call(this);
		this.on("click",this,this.onClick);
	}

	__class(BossHarmReward,'view.modules.bossHall.sanjieBoss.BossHarmReward',_super);
	var __proto=BossHarmReward.prototype;
	Laya.imps(__proto,{"com.xq.view.modules.bossHall.sanjieBoss.IBossHarmReward":true})
	__proto.onClick=function(){
		if(this.hasReward){
			Mgr.jindiPro.sendGetBossHarmReward(this.curRewardId);
			if(this.rewardItems){
				this.rewardItems.fly();
			}
		}
	}

	__proto.update=function(){
		var msg=Mgr.jindi.getBossHarmInfo(this.monsterId);
		if(msg){
			var arr=msg.rewards;
			var ln=arr.length;
			var info;
			this.hasReward=false;
			for (var i=0;i < ln;i++){
				info=arr[i];
				this.nextTargetHarmValue=info.needHarm;
				if(info.reached && !info.isGetReward){
					this.hasReward=true;
					this.curRewardId=info.rewardId;
				}
				if(!info.reached){
					break ;
				}
			}
			this.showReward(info.rewardId);
			if(this.hasReward){
				this.harmInfo.visible=false;
				this.harmtip.visible=false;
				this.canget.visible=true;
				this.rewardItems.mouseEnabled=false;
				if(!this._ani){
					this._ani=new UIAni;
					this._ani.setRes(PathDefine.EFFECT_UI+"liuguang_01.amt");
					this._ani.pos(0,0);
					this.spr.addChild(this._ani);
				}
				this.img_got.visible=false;
			}
			else{
				this.harmInfo.visible=true;
				this.harmtip.visible=true;
				this.canget.visible=false;
				this.rewardItems.mouseEnabled=true;
				if(this._ani){
					this._ani.recover();
					this._ani=null;
				}
				this.img_got.visible=info.rewardId==arr[ln-1].rewardId&&info.isGetReward;
			}
			this.updateHarm();
		}
	}

	__proto.showReward=function(rewardId){
		if(this.rewardItems==null){
			this.rewardItems=new ItemDisplayList();
			this.spr.addChild(this.rewardItems);
		};
		var arr=Mgr.jindi.getHarmRewardById(rewardId);
		if(arr){
			this.rewardItems.showItems(arr);
			var bag=this.rewardItems.getItemV(0);
			if(bag){
				var itemVo=bag.dataSource;
				if(itemVo){
					this.itemName.text=itemVo.cfgItem.name;
				}
			}
		}
	}

	__proto.onOpened=function(){
		this.monsterId=Mgr.jindi.bossId;
		this.itemName.text="";
		this.myHarmValue=0;
		EventCenter.instance.on("BOSS_HARM_Reward_INFO",this,this.update);
		EventCenter.instance.on("update_rank_fightinfo",this,this.onHarmRankData);
		this.update();
	}

	__proto.close=function(){
		EventCenter.instance.off("BOSS_HARM_Reward_INFO",this,this.update);
		EventCenter.instance.off("update_rank_fightinfo",this,this.onHarmRankData);
		if(this._ani){
			this._ani.dispose();
			this._ani=null;
		}
	}

	__proto.onHarmRankData=function(arr){
		var myRoleId=NetMgr.ins().roleVO.guid;
		for (var i=0;i < arr.length;i++){
			var harm=arr[i];
			if(harm.roleId==myRoleId){
				this.myHarmValue=harm.power;
				this.updateHarm();
				break ;
			}
		}
	}

	__proto.updateHarm=function(){
		this.harmInfo.text=CommonUtil.numFormat2(this.nextTargetHarmValue);
	}

	return BossHarmReward;
})(BossHarmRewardUI)


