		var equipJie=parseInt(cof.equipJie);
		if(htype==1){
			var type=parseInt(cof.type);
			var floor=parseInt(cof.floor);
			var arr=Mgr.wuLinHuanJingM.getBossArr(htype,type,floor);
			var index=(floor-1)%arr.length;
			var ysCof=arr[index].getCfgData();
			this._monsterId=ysCof.bossId;
			}else{
			if(equipJie){
				this._monsterId=cof.monster;
				}else{
				this._monsterId=cof.monsterid;
			}
		};
		var bossCof=Model.monster.getMonsterCfgById(this._monsterId);
		if(!bossCof)return;
		this.txt_lv.text="LV."+bossCof.level;
		if(htype==1){
			this.txt_boss.text=Lang.str(476)+cof.floor+Lang.str(612);
			this.txt_desc.text=bossCof.name
			}else{
			if(equipJie){
				this.txt_boss.text=cof.jie;
				this.txt_desc.text=bossCof.name;
				}else{
				this.txt_boss.text=bossCof.name;
				this.txt_desc.text=cof.outDesc;
			}
		}
		this._ifGuanZhu=Mgr.bossRefreshMgr.checkIfGuanZhu(this._monsterId);
		this.box_stat.visible=this._ifGuanZhu;
