//class view.modules.chaoZhiLiBao.ChongBangLiBaoCZView extends ui.modules.chaoZhiLiBao.ChongBangLiBaoUI
var ChongBangLiBaoCZView=(function(_super){
	function ChongBangLiBaoCZView(){
		this.cblbMgr=null;
		this.teShuItem=null;
		/**现价*/
		this.xianjia=0;
		this.dateAry=null;
		/**当前可购买最大次数*/
		this.maxCiShu=0;
		ChongBangLiBaoCZView.__super.call(this);
	}

	__class(ChongBangLiBaoCZView,'view.modules.chaoZhiLiBao.ChongBangLiBaoCZView',_super);
	var __proto=ChongBangLiBaoCZView.prototype;
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
		this.cblbMgr=Mgr.chaoZhiLiBaoMgr;
		this.btn_lq.on("click",this,this.onReward);
		this.html_miaoshu.style.align="center";
		this.html_time.style.align="center";
		this.html_time.style.fontSize=24;
		this.html_miaoshu.style.fontSize=24;
	}

	__proto.open=function(){
		this.cblbMgr.hideCBRed(false);
		EventCenter.instance.onQue("CBLB_INFO",this,this.initData);
		EventCenter.instance.onQue("CBLB_REWARD",this,this.upData);
		EventCenter.instance.onQue("CBLB_REWARD",this,this.itemFly);
		Mgr.chaoZhiLiBaoProMgr.sendCbzkInfoCS();
	}

	__proto.initData=function(){
		if(this.cblbMgr.isActivity){
			this.html_time.visible=false;
			}else{
			this.html_time.visible=true;
			this.changeTime();
			if(this.cblbMgr.mrlcTime > Mgr.curTime.serverTimer){
				Laya.timer.loop(1000,this,this.changeTime);
			}
		}
		this.upData();
	}

	__proto.upData=function(){
		var arr_data=this.cblbMgr.getCblbData();
		var length=arr_data.length;
		var obj=this.cblbMgr.getData(this.cblbMgr.propId,this.cblbMgr.cblbCfg);
		if(obj){
			if(!this.teShuItem)this.teShuItem=new ItemDisplayList();
			this.teShuItem.y=745;
			this.addChild(this.teShuItem);
			var sell=obj.prop.split(";");
			this.teShuItem.showItems(sell,10,100,80,1);
			this.teShuItem.showHorCenter(this.width);
			this.xianjia=obj.dprice;
			this.label_txt1.text=Lang.str(688)+obj.price;
			this.label_txt2.text=Lang.str(689)+this.xianjia;
			this.label_name.text=obj.lbname;
			var micon=PathDefine.RES2_ROOT+PathDefine.CURRENCYICON+"2"+".png";
			this.mc_yb1.skin=micon;
			this.mc_yb2.skin=micon;
			this.cblbMgr.dangQianZheKou=obj.discount;
			this.setHtmlMiaoshu(obj.discount,parseInt(obj.id));
		}
		this.list.array=arr_data;
		this.setSvipTxt();
		this.dateAry=arr_data;
		this.updatePro();
	}

	/**更新进度条*/
	__proto.updatePro=function(){
		var curVal=this.cblbMgr.buyCount;
		var kdAry=this.getKeDuAry();
		var len=kdAry.length;
		var endKd=0;
		var tempKd=0;
		var tempIndex=0;
		for (var i=0;i < len;i++){
			var gapN=parseInt(kdAry[i])
			if(tempIndex==0){
				if(curVal < gapN){
					tempIndex=i;
					endKd=gapN;
					break
				}
				else {
					tempKd=gapN;
				}
			}
		};
		var tempVal=0;
		var hasExtra=kdAry.indexOf(curVal.toString())==-1;
		if(curVal > 0){
			tempIndex=tempIndex-1;
			if(tempIndex >=0){
				if(hasExtra){
					tempIndex+=((curVal-tempKd)/(endKd-tempKd));
				}
				tempVal=tempIndex/(len-1);
			}
			else{
				tempVal=1;
			}
		}
		this.prog_jd.value=tempVal
	}

	/**获取刻度值*/
	__proto.getKeDuAry=function(){
		var temp=[];
		if(this.dateAry){
			var len=this.dateAry.length
			for (var i=0;i < len;i++){
				var tp=this.dateAry[i];
				temp.push(tp.openNum);
			}
		}
		return temp;
	}

	__proto.setHtmlMiaoshu=function(zhe,id){
		var nextObj=this.cblbMgr.getData(id+1,this.cblbMgr.cblbCfg);
		var shuliang=0;
		if(nextObj){
			shuliang=nextObj.openNum;
		}
		if(shuliang==0){
			shuliang=this.cblbMgr.getFlagXG(NetMgr.ins().roleVO.vipLevel);
		}
		this.html_miaoshu.innerHTML=CodeMgr.ins.getStringByCode([260748,(zhe*10),shuliang-this.cblbMgr.buyCount]);
	}

	__proto.setSvipTxt=function(){
		var roleVO=NetMgr.ins().roleVO;
		var svip=roleVO.vipLevel;
		var obj={};
		var ji=0;
		if(roleVO.vipLevel < 2){
			ji=this.cblbMgr.getFlagXG(0);
			}else{
			ji=this.cblbMgr.getFlagXG(roleVO.vipLevel);
		}
		this.maxCiShu=ji;
		obj=this.cblbMgr.getSvipXG(svip+1);
		if(obj==null || obj.svip==0){
			var vipMax=Mgr.vipcfgMgr.maxSvipLv;
			for (var i=0;i < vipMax;i++){
				svip=svip+1;
				obj=this.cblbMgr.getSvipXG(svip);
				if(obj){
					break ;
				}
			}
		}
		this.label_ygm.text=this.cblbMgr.buyCount+"/"+ji+Lang.str(690);
		if(obj){
			this.label_Svip.text="SVIP"+obj.svip+Lang.str(691);
			this.label_kgm.text=obj.buyNum+Lang.str(690);
			this.box_yigou.x=143;
			}else{
			this.box_yigou.x=265;
			this.label_Svip.text="";
			this.label_kgm.text="";
		}
	}

	__proto.changeTime=function(){
		var time=this.cblbMgr.mrlcTime-Mgr.curTime.serverTimer;
		var a=CommonUtil.formatDate(time,4,false);
		this.html_time.innerHTML=CodeMgr.ins.getStringByCode([160536,a]);
	}

	__proto.onReward=function(){
		var roleVO=NetMgr.ins().roleVO;
		if(this.cblbMgr.buyCount < this.maxCiShu){
			if(roleVO.yuanbao >=this.xianjia){
				Mgr.chaoZhiLiBaoProMgr.sendCbzkRewardCS(this.cblbMgr.propId);
				}else{
				UIMgr.ins.openView(YuanBaoBuZuView,2);
			}
			}else{
			if(this.cblbMgr.buyCount==this.cblbMgr.getFlagXG(roleVO.vipLevel+1)){
				Mgr.prompt.optionPrompt(Lang.str(692));
				}else{
				var vipTiShi=UIMgr.ins.openView(YuanBaoBuZuView,2);
				vipTiShi.setTiShi(Lang.str(693));
			}
		}
	}

	/**道具购买成功后飞*/
	__proto.itemFly=function(){
		this.teShuItem.fly();
	}

	__proto.dispose=function(){
		this.bg.disposeLater();
		this.img_banner.disposeLater();
		Laya.timer.clear(this,this.changeTime);
		EventCenter.instance.offQue("CBLB_INFO",this,this.initData);
		EventCenter.instance.offQue("CBLB_REWARD",this,this.upData);
		EventCenter.instance.offQue("CBLB_REWARD",this,this.itemFly);
	}

	return ChongBangLiBaoCZView;
})(ChongBangLiBaoUI)


