//class view.modules.common.AttributeItem1 extends ui.modules.common.AttributeItem1UI
var AttributeItem1=(function(_super){
	function AttributeItem1(){
		AttributeItem1.__super.call(this);
	}

	__class(AttributeItem1,'view.modules.common.AttributeItem1',_super);
	var __proto=AttributeItem1.prototype;
	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		this._dataSource=value;
		if(!value)return;
		if((value instanceof com.xq.vo.PropAttrVo )){
			this.atrName.text=value.cnName;
			this.atrVal.text=value.ifPer?"+"+value.attrVal+"%":"+"+value.attrVal;
			if(value.color){
				this.atrVal.color=this.atrName.color=value.color
			}
			if(value.cloVal){
				this.atrVal.color=value.cloVal;
			}
		}
		else{
			this.atrName.text=value.attrName;
			if(value.attrVal >=0){
				if(value.attrName==Lang.str(700)){
					this.atrVal.text="+"+(Math.round((value.attrVal)*100)/100).toFixed(0)+"%";
					this.atrName.text=value.moduleStr+value.attrName;
				}
				else{
					this.atrVal.text="+"+value.attrVal;
				}
			}
			else
			this.atrVal.text="";
			if(value.isPer)
				this.atrVal.text="+"+(parseFloat(value.attrVal)*100).toFixed(2)+"%";
			if(value.cloName)
				this.atrName.color=value.cloName;
			if(value.cloVal)
				this.atrVal.color=value.cloVal;
		}
		this.ctBox.refresh();
	});

	return AttributeItem1;
})(AttributeItem1UI)


