		var curAttr;
		var nextAttr;
		for(var i=0;i<len;i++){
			item=CommonAttrItem.getItem();
			curAttr=this._curArr[i];
			nextAttr=this._nextArr?this._nextArr[i]:null;
			item.setData(curAttr,nextAttr);
			var row=i%this._row;
			if(!this._itemDic.get(row)){
				this._itemDic.set(row,[]);
			}
			this._itemDic.get(row).push(item);
			this._items.push(item);
		}
