var ChaojiZhiGouView=(function(_super){
	function ChaojiZhiGouView(){
		this._mgr=null;
		this._action=null;
		/**奖励*/
		this._reward=null;
		/**当前选中的Ele*/
		this._curSelectEle=null;
		this._ani=null;
		/**剩余活动时间*/
		this._time=NaN;
		ChaojiZhiGouView.__super.call(this);
	}

	__class(ChaojiZhiGouView,'view.modules.chaojizhigou.ChaojiZhiGouView',_super);
	var __proto=ChaojiZhiGouView.prototype;
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
		CommonUtil.listSetScroll(this.list);
		this._mgr=Mgr.chaoJiZhiGouM;
		this._action=Mgr.kflbAction;
		this.list.selectHandler=Handler.create(this,this.selectLiBao,null,false);
	}

	__proto.open=function(){
		this.startListener();
		this.startTimer();
		this.list.array=this._mgr.getShowArr();
		this._action.sendGetLiBaoInfo(14);
		this.list.selectedIndex=this._mgr.getSelectIndex(this.list.array);
	}

	__proto.startListener=function(){
		this.btn_buy.on("click",this,this.onClick);
		EventCenter.instance.on("UpdateInfo",this,this.updateInfo);
	}

	__proto.onClick=function(){
		if(!this._curSelectEle)return;
		var state=this._mgr.checkEleStat(this._curSelectEle);
		var cfg=this._curSelectEle.getCfgData();
		if(state==1){
			var id=parseInt(cfg.id);
			this._action.sendLiBaoReward(14,id);
			}else if(state==0){
			var czId=parseInt(cfg.rechageId);
			if(Configs.isOpenCZ){
				Mgr.chatPro.sendDebugMsg("@ add directrmb "+czId);
			}
			else{
				Mgr.vip.sendJHSDKCharege(0,czId,"");
			}
		}
	}

	__proto.updateInfo=function(){
		this.list.array=this._mgr.getShowArr();
		var index=this._mgr.getSelectIndex(this.list.array);
		if(index!=this.list.selectedIndex){
			this.list.selectedIndex=index;
			}else{
			this.refreshView();
		}
	}

	__proto.selectLiBao=function(index){
		if(index==-1)return;
		this.refreshView();
	}

	__proto.refreshView=function(){
		var ele=this.list.array[this.list.selectedIndex];
		if(!ele)return;
		this._curSelectEle=ele;
		var cfg=ele.getCfgData();
		var url=this._mgr.getUrlBySex(cfg);
		var state=this._mgr.checkEleStat(this._curSelectEle);
		this.v_fight.setFight=parseInt(cfg.power);
		this.box.visible=cfg.discount&&state==0;
		this.btn_buy.disabled=state>1;
		CornerUtil.removeCorner(this.btn_buy);
		if(this.box.visible){
			this.txt_zhekou.text=cfg.discount+Lang.str(694);
		}
		if(state==0){
			this.txt_desc.text=Mgr.chargeMgr.getRmbByID(cfg.rechageId)+Lang.str(404);
			}else if(state==1){
			this.txt_desc.text=Lang.str(362);
			CornerUtil.addCorner(this.btn_buy);
			}else{
			this.txt_desc.text=Lang.str(430);
		}
		if(!this._reward){
			this._reward=new ItemDisplayList();
			this.sp_reward.addChild(this._reward);
		}
		if(!this._ani){
			this._ani=new DisplayAni();
			this.sp_ani.addChild(this._ani);
		}
		this._ani.setResWithScale(url);
		var rewardArr=cfg.rewards.split(";");
		this._reward.showItems(rewardArr,10,100,100,1);
		this._reward.showHorCenter(this.sp_reward.width);
	}

	/**启动活动计时器*/
	__proto.startTimer=function(){
		this._time=NewActiveManager.ins.getTimeLeft(218);
		if(this._time>0){
			Laya.timer.loop(1000,this,this.refreshiTime);
			this.txt_time.text=CommonUtil.formatDate(this._time,4,false);
		}
		else{
			this.txt_time.text=Lang.str(410);
		}
	}

	__proto.refreshiTime=function(){
		this._time-=1000;
		if(this._time <=0){
			Laya.timer.clear(this,this.refreshiTime);
			this.txt_time.text=Lang.str(365);
			this.txt_time.color="#ff4141";
			this.btn_buy.disabled=true;
			return;
		}
		this.txt_time.color="#4dff55";
		this.txt_time.text=CommonUtil.formatDate(this._time,4,false);
	}

	__proto.stopListener=function(){
		EventCenter.instance.off("UpdateInfo",this,this.updateInfo);
		this.btn_buy.off("click",this,this.onClick);
	}

	__proto.dispose=function(){
		this._curSelectEle=null;
		this.stopListener();
		if(this._ani){
			this._ani.dispose();
			this._ani=null;
		}
		this.list.selectedIndex=-1;
		this.bg.disposeLater();
		var len=this.list.array.length;
		var item;
		for(var i=0;i<len;i++){
			item=this.list.cells [i];
			if(item){
				item.dispose();
			}
		}
	}

	return ChaojiZhiGouView;
})(ChaoJiZhiGouViewUI)


