		var compArr=this.vo.compound.split(";");
		for (var i=0;i < this.maxMaterial;i++){
			var txt_need=this["txt_need"+i];
			if(compArr[i]){
				var itemArr=compArr[i].split(":");
				var materialNum=Mgr.newBagM.getItemCount(itemArr[0]);
				txt_need.text=materialNum+"/"+itemArr[1];
				txt_need.visible=true;
				if(materialNum >=parseInt(itemArr[1]))
					txt_need.color="#d4e7f9";
				else
				txt_need.color="#ff4141";
			}
			else{
				txt_need.visible=false;
			}
		}
