		if(!baGuaInfoSC)
			return;
		var strName="";
		if(this.curZhenYingType==1){
			strName=Lang.str(757);
			}else{
			strName=Lang.str(758);
		}
		this.clipLevel.text=strName+baGuaInfoSC.daoFaLevel+Lang.str(251);
