	__proto.finish=function(){
		if(!this.filterArr)return;
		var len=this.filterArr.length;
		for (var i=0;i < len;i++){
			var icon=this.equipList.cells [i];
			if(!icon)debugger
				Laya.timer.once(Math.floor(i/5)*100,this,this.playAni,[icon,i],false);
		}
		if(Mgr.equip.isAutoSmelt){
			Laya.timer.once(Math.floor(len/5)*480,this,this.onSmeltAll);
		}
		else{
			this.btnAllSmelt.disabled=false;
		}
	}

