//class view.modules.activity.chongbangxiaofei.ChongBangXiaoFei extends ui.modules.operationActivity.ChongBangXiaoFeiUI
var ChongBangXiaoFei=(function(_super){
	function ChongBangXiaoFei(){
		this.actTime=NaN;
		ChongBangXiaoFei.__super.call(this);
	}

	__class(ChongBangXiaoFei,'view.modules.activity.chongbangxiaofei.ChongBangXiaoFei',_super);
	var __proto=ChongBangXiaoFei.prototype;
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
		CommonUtil.listSetScroll(this.xfList,false);
		this.btn_jihuo.on("click",this,this.onQianWanJiHuo);
	}

	__proto.onQianWanJiHuo=function(){
		Mgr.cslMgr.onQianWanJiHuo();
	}

	__proto.flush=function(){
		this.xfList.array=Mgr.cbxfMgr.getCfgByType();
		this.xfList.tweenTo(0);
	}

	__proto.daojishi=function(){
		var temp=this.actTime-Mgr.curTime.serverTimer;
		if(temp <=0){
			this.timeTxt.text=Lang.str(365);
		}
		else{
			this.timeTxt.text=CommonUtil.formatDate(temp,4,false);
		}
	}

	__proto.open=function(){
		this.flush();
		var vo=NewActiveManager.ins.getActiveVerDic(48);
		if(vo){
			this.actTime=vo.endTime;
			Laya.timer.loop(1000,this,this.daojishi);
		}
		EventCenter.instance.on("GetTargetRewardOpraEvent",this,this.flush);
		EventCenter.instance.on("UpDataTargetInfoOpraEvent",this,this.flush);
		if(Mgr.activityTipMgr.hasBoughtShouChong && Mgr.cslMgr.isBuy){
			this.btn_jihuo.visible=false;
			this.mc_yjh.visible=true;
			}else{
			this.btn_jihuo.visible=true;
			this.mc_yjh.visible=false;
		}
	}

	__proto.dispose=function(){
		Mgr.sinImgMgr.add(this.bg);
		Mgr.sinImgMgr.add(this.mc_bg);
		Laya.timer.clear(this,this.daojishi);
		EventCenter.instance.off("GetTargetRewardOpraEvent",this,this.flush);
		EventCenter.instance.off("UpDataTargetInfoOpraEvent",this,this.flush);
	}

	return ChongBangXiaoFei;
})(ChongBangXiaoFeiUI)


