//class view.modules.equipTip.EquipTipBaseView extends ui.modules.equipTip.EquipTipBaseUI
var EquipTipBaseView=(function(_super){
	function EquipTipBaseView(){
		EquipTipBaseView.__super.call(this);
	}

	__class(EquipTipBaseView,'view.modules.equipTip.EquipTipBaseView',_super);
	var __proto=EquipTipBaseView.prototype;
	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if (!value)return;
		var o=value;
		var strenValue=0;
		if (o.strengthAttrs.length > 0){
			var stren=o.strengthAttrs[0];
			strenValue=stren.attrValue;
		}
		for (var i=0;i < o.attrArr.length;i++){
			var attrVO=o.attrArr[i];
			if(!attrVO)continue ;
			var box=new Box();
			box.height=26;
			box.x=-14;
			var html=new HTMLDivElement();
			html.style.fontSize=22;
			html.style.color="#d4e7f9";
			html.style.font="SimHei";
			html.width=360;
			html.innerHTML="<span color='#cbdff2'>"+attrVO.attrCName+" +"+attrVO.attrValue+"</span>";
			box.addChild(html);
			this.vBox.addChild(box);
			this.vBox.height+=30;
		}
		this.height=this.vBox.height+35;
		if(o.whichPanel==8 || o.whichPanel==0){
			this.compareVBox.visible=true;
			var curEquipData=Mgr.equip.getItemVo(1,o.partPos);
			var curEquip=curEquipData?Mgr.equip.createEquipVO(curEquipData.msg):null;
			for (i=0;i < o.attrArr.length;i++){
				attrVO=o.attrArr[i];
				box=new Box();
				box.height=26;
				box.y=i+33;
				html=new HTMLDivElement();
				html.style.fontSize=22;
				html.style.color="#d4e7f9";
				html.style.font="SimHei";
				html.width=360;
				html.x=30;
				var hint=new Image();
				hint.height=17;
				hint.width=15;
				hint.x=10;
				if(curEquip){
					var curAttrVO=curEquip.attrArr[i];
					var dif=0;
					if(curAttrVO){
						dif=parseInt(curAttrVO.attrValue)-parseInt(attrVO.attrValue);
						}else{
						dif=-parseInt(attrVO.attrValue);
					}
					if(dif > 0){
						hint.skin="modules/common/hint1.png";
						}else if(dif==0){
						html.x=65+50;
						hint.skin="modules/common/hintLine.png";
						hint.y=2;
						hint.x=10+50;
						}else{
						hint.skin="modules/common/hint2.png";
					}
					html.innerHTML="<span color='#cbdff2'>"+(Math.abs(dif))+"</span>";
					hint.visible=true;
					}else{
					hint.visible=false;
					html.innerHTML="<span color='#cbdff2'>"+Lang.str(428)+"</span>";
				}
				box.addChild(hint);
				box.addChild(html);
				this.compareVBox.addChild(box);
				this.compareVBox.height+=30;
			}
			}else{
			this.compareVBox.visible=false;
		}
		if (Mgr.equip.isObserv && o.whichPanel==11){
			var observE=Mgr.equip.observE;
			var obStrenv=0;
			if (observE.strengthAttrs.length > 0){
				var obAttr=observE.strengthAttrs[0];
				obStrenv=obAttr.attrValue;
			};
			var attrVO0=o.attrArr[0];
			var obVO0=observE.attrArr[0];
			var len=observE.attrArr.length;
			if(len !=1){
				for (var j=0;j < len;j++){
					if(observE.attrArr[j].attrId==attrVO0.attrId)
						obVO0=observE.attrArr[j];
				}
			};
			var v=(parseInt(attrVO0.attrValue)+strenValue)-(parseInt(obVO0.attrValue)+obStrenv);
			if (v > 0){
				this.up.visible=true;
				this.down.visible=false;
				this.fv.visible=true;
				this.fv.color="#4dff55";
			}
			else if (v < 0){
				this.up.visible=false;
				this.down.visible=true;
				this.fv.visible=true;
				this.fv.color="#ff4141";
			}
			else{
				this.up.visible=false;
				this.down.visible=false;
				this.fv.visible=false;
			}
			this.fv.text=v.toString();
		}
		else{
			this.up.visible=false;
			this.down.visible=false;
			this.fv.visible=false;
		}
	});

	return EquipTipBaseView;
})(EquipTipBaseUI)


