	var __proto=BianCeFanLiItem.prototype;
	__proto.onReward=function(){
		if(this.btn_lq.label==Lang.str(362)){
			if(this._dataSource){
				if(Mgr.bag.hasEnoughGrids(this.ele.getCfgData().rewardItem1,true)){
					Mgr.opeAct.sendGetActivityReward(Mgr.leiChongHaoLiMgr.curAct,this.ele.getCfgData().id);
					if(this.teShuItem){
						this.teShuItem.fly();
					}
				}
			}
			}else{
			if(Mgr.leiChongHaoLiMgr.curAct==103){
				UIMgr.ins.openView(BianCeXingDongFrame,1,0)
				}else{
				UIMgr.ins.openView(KaiXueQingDianFrame,1,0)
			}
		}
	}

