	__proto.startListener=function(){
		this.on("click",this,this.onClick);
	}

	__proto.stopListener=function(){
		this.off("click",this,this.onClick);
	}

	__proto.setData=function(value){
		if(!value)return;
		this.startListener();
		this._vo=value;
		this._curId=this._vo.curId;
		this.txt_lv.text=CommonUtil.getNum(this._curId)+Lang.str(251);
		this._finishTime=this._vo.finishTime;
		this._time=this._finishTime-Mgr.curTime.serverTimer;
		if((this._vo instanceof com.xq.proto.gen.husong.HuSongOtherMsg )){
			this._ifmyBeauty=false;
			this.txt_lv.x=(this.box_time.width-this.txt_lv.width)/2;
			this.txt_time.visible=false;
			Laya.timer.clear(this,this.onCountDown);
		}
		else if((this._vo instanceof com.xq.proto.gen.husong.HuSongMsg )){
			this.txt_lv.x=0;
			this._ifmyBeauty=true;
			this.txt_time.visible=true;
			this.txt_time.changeText(CommonUtil.formatDate(this._time,15,false));
			Laya.timer.loop(1000,this,this.onCountDown);
		}
		this._aniNum=1;
		this._anis=[];
		if(Mgr.escortBeautyM.ifDouble){
			this._aniNum++;
		}
		if(this._vo.hasExtra){
			this._aniNum++;
		}
		for(var i=0;i<this._aniNum;i++){
			var ani=new UIAni();
			ani.zOrder=-i;
			ani.scaleY=ani.scaleX=1-i*(0.05);
			this.sp_ani.addChild(ani);
			ani.setRes(PathDefine.getBiaoChe(this._curId));
			ani.y=-i*(30);
			this._anis.push(ani);
		}
		this.zOrder=0;
	}

	__proto.onCountDown=function(){
		this._time=this._finishTime-Mgr.curTime.serverTimer;
		if(this._time<=0){
			Laya.timer.clear(this,this.onCountDown);
			return;
		}
		this.txt_time.changeText(CommonUtil.formatDate(this._time,15,false));
	}

	__proto.onClick=function(){
		if(this._ifmyBeauty){
			var v1=UIMgr.ins.openView(MyEscortInfo,2);
			v1.dataSource=this._vo;
		}
		else{
			var v2=UIMgr.ins.openView(OtherEscortInfo,2);
			v2.dataSource=this._vo;
		}
	}

	/**移动*/
	__proto.move=function(add){
		this.x+=add;
		if(this.x>=750){
			this.x=-328;
			this.zOrder++;
		}
	}

	__proto.removeAni=function(){
		if(!this._anis)return;
		var len=this._anis.length;
		for(var i=0;i<len;i++){
			this._anis[i]&&this._anis[i].dispose();
		}
		this._anis.length=0;
	}

	__proto.dispose=function(){
		this.stopListener();
		this.img_beauty.skin=null;
		Laya.timer.clear(this,this.onCountDown);
		this._vo=null;
		this._ifmyBeauty=false;
		this.removeAni();
		this.removeSelf();
		view.modules.escortBeauty.view.BeautyMoveItem.recover(this);
	}

