		this.fengshenluRank.rank=vo.myRank;
		this.txt_helpFight.text=Lang.str(940)+(this.mgr.teamMaxInviteNum-vo.teamInvitation);
		this.curSelectBarrier=this.mgr.maxId;
		for (var j=0;j < this.showRankNum;j++){
			if(this.mgr.fengshenRank[j]){
				var roleName=CommonUtil.sliceName(this.mgr.fengshenRank[j].roleName);
				this["txt_name"+j].text=roleName;
				this["txt_rank"+j].text=this.mgr.fengshenRank[j].tongGuanNum+"";
			}
			else{
				this["txt_name"+j].text="";
				this["txt_rank"+j].text="";
			}
		}
		this.updateRender(this.curSelectBarrier);
