				var itemVO=Mgr.item.getItemVO(this._showMinTimeObj.jiangli.split(";")[0].split(":")[0]);
				this.img_item.skin=PathDefine.getIconUrl(itemVO.cfgItem.url);
				this.txt_time.text=CommonUtil.formatDate(this._showMinTimeObj.timeDown,1,false);
				if(this._showMinTimeObj.type=="XianShi"){
					this._showMinTimeObj.timeDown-=1000;
				}
				this.lingQuRewardAni.visible=false;
				Laya.timer.clear(this,this.refreshTime);
