		EventCenter.instance.off(view.modules.guanka.CMGuanKa.CMGQ_SCROLL,this,this.onSaoDanBack);
		EventCenter.instance.off("DuoBeiTuBiao",this,this.refreshStart);
		EventCenter.instance.off("GK_TIAOZHAN",this,this.updateListData);
