var GuildMemView=(function(_super){
	function GuildMemView(){
		this.model=null;
		this.redDic=null;
		GuildMemView.__super.call(this);
	}

	__class(GuildMemView,'view.modules.guild.GuildMemView',_super);
	var __proto=GuildMemView.prototype;
	Laya.imps(__proto,{"com.xq.view.modules.guild.IGuildMemView":true})
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
		this.model=Mgr.guild.model;
		this.guilList.vScrollBarSkin="";
		CommonUtil.listSetScroll(this.guilList,false);
		this.redDic=Mgr.red.getValue("zongmenchengyuan");
	}

	__proto.open=function(){
		EventCenter.instance.on("GUILD_INFO_UPDATE",this,this.onGuildInfoUpdate);
		Mgr.guildPro.sendGetGuildInfo(0);
		this.model.applyDic.values;
		this.onGuildInfoUpdate();
	}

	__proto.dispose=function(){
		EventCenter.instance.off("GUILD_INFO_UPDATE",this,this.onGuildInfoUpdate);
	}

	__proto.onGuildInfoUpdate=function(){
		var vo=NetMgr.ins().roleVO;
		if(vo.guildTitle==PositionDefine.MASTER){
			this.lblPosition.skin="modules/guild/zongzu.png";
			}else if(vo.guildTitle==PositionDefine.FUMASTER){
			this.lblPosition.skin="modules/guild/fuzongzu.png";
			}else if(vo.guildTitle==PositionDefine.ZHANGLAO){
			this.lblPosition.skin="modules/guild/zhanglao.png";
		}else
		this.lblPosition.skin="modules/guild/putong.png";
		this.lblHistory.changeText(""+vo.contribute);
		var guildInfo=Mgr.guild.model.myGuildInfoMsg;
		if(guildInfo && guildInfo.members){
			var onLine=[];
			var offLine=[];
			var memArray=guildInfo.members;
			var info;
			for(var $each_info in memArray){
				info=memArray[$each_info];
				if(info.isOnline)
					onLine.push(info);
				else
				offLine.push(info);
			}
			onLine=onLine.sort(this.sortMems);
			offLine=offLine.sort(this.sortMems);
			this.guilList.array=onLine.concat(offLine);
		}
	}

	/**宗门成员大排序*/
	__proto.sortMems=function(a,b){
		if(a.position>b.position)
			return 1;
		else if(a.position<b.position)
		return-1;
		else{
			if(a.offlineTime<b.offlineTime)
				return-1;
			else if(a.offlineTime>b.offlineTime)
			return 1;
			else{
				if(a.totalContribution<b.totalContribution)
					return 1;
				else if(a.totalContribution>b.totalContribution)
				return-1;
				else{
					if(a.fightValue < b.fightValue)
						return 1;
					else if(a.fightValue > b.fightValue)
					return-1;
					else{
						if(a.level < b.level)
							return 1;
						else if(a.level>b.level)
						return-1;
						else
						return 0;
					}
				}
			}
		}
	}

	return GuildMemView;
})(GuildMemUI)


