		this.box_jinJie.visible=false;
		var gaoJiArr=CommonUtil.getListAryByCfg(cfg,"","",false,0.5);
		this.list_jiHuoAttr.array=gaoJiArr;
		var wanMeiArr=CommonUtil.getListAryByCfg(cfg);
		this.list_jiHuoAttr2.array=wanMeiArr;
		var jiHuoNumArr=cfg.activate.split(";");
		var len=jiHuoNumArr.length;
		this.gaojiNum=parseInt(jiHuoNumArr[0]);
		if(this.curNumIsActivity(this.gaojiNum,ser.activeNum)){
			this.btn_jiHuo.visible=false;
			this.img_yiJiHuo1.visible=true;
			curFight=AttributeTypeEnum.getAttrArrTotalFVByCfgMsg(cfg)*0.5;
			this.txt_gaoji.text=Lang.str(1239);
			this.multiplyNum+=0.5;
			}else{
			this.btn_jiHuo.visible=true;
			this.img_yiJiHuo1.visible=false;
			if(this.gaojiNum==0){
				this.txt_gaoji.text=Lang.str(1240)+this.getReachNum(cfg)+"/"+(this.gaojiNum+1)+")";
				}else{
				this.txt_gaoji.text=Lang.str(1240)+this.getReachNum(cfg)+"/"+this.gaojiNum+")";
			}
		}
		this.wanMeiNum=parseInt(jiHuoNumArr[1]);
		if(this.curNumIsActivity(this.wanMeiNum,ser.activeNum)){
			this.btn_jiHuo2.visible=false;
			this.img_yiJiHuo2.visible=true;
			curFight+=AttributeTypeEnum.getAttrArrTotalFVByCfgMsg(cfg)*0.5;
			this.txt_wanMei.text=Lang.str(1241);
			isActivity=true;
			this.multiplyNum+=0.5;
			}else{
			this.btn_jiHuo2.visible=true;
			this.img_yiJiHuo2.visible=false;
			this.txt_wanMei.text=Lang.str(1242)+this.getReachNum(cfg)+"/"+this.wanMeiNum+")";
		}
		this.powerV.setFight=curFight;
		this.mc_wjh.visible=true;
		this.txt_state.visible=false;
		var skillVo=SkillManager.ins.getData(cfg.hejiskill);
		this.txt_skill.text=skillVo.name;
		this.curCfg=cfg;
