		this.txt_once.color=this._bagCount>=this._onceItemCount?"#4dff55":"#ff4141";
		this.txt_ten.changeText(this._bagCount+"/"+this._tenItemNeedCount);
		this.txt_ten.color=this._bagCount>=this._tenItemNeedCount?"#4dff55":"#ff4141";
