		Laya.timer.clear(this,this.sendKaiXueQingDianInfo);
		Laya.timer.clear(this,this.refreshTime);
		EventCenter.instance.off("qing_dian_resresh",this,this.refreshPanel);
		EventCenter.instance.off("KaiXueQingDianFrameRed",this,this.refreshCostRed);
