//class view.modules.hancock.HancockRankItem extends ui.modules.ranKingList.CommonRankItemUI
var HancockRankItem=(function(_super){
	function HancockRankItem(){
		this._mgr
		HancockRankItem.__super.call(this);
		this.v_rank.type=1;
		this.img_pro.visible=true;
		this._mgr=Mgr.hancock
	}

	__class(HancockRankItem,'view.modules.hancock.HancockRankItem',_super);
	var __proto=HancockRankItem.prototype;
	// v_rank.rank=rank;
	__proto.dispose=function(){
		this.v_rank.dispose();
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		Laya.superSet(CommonRankItemUI,this,'dataSource',value);
		if(!value)return;
		var ele=value;
		var rank=ele.getValue("Rank");
		this.v_rank.rank=rank;
		this.img_pro.width=0;
		if(this._mgr.rankState==0){
			var info=ele.getValue("preRank");
			if(!info){
				var cfg=ele.getCfgData();
				var limit=parseInt(cfg.limit);
				this.txt_layer.text=limit? CommonUtil.numFormat(limit,1)+Lang.str(976):Lang.str(428);
				this.txt_name.text=Lang.str(394);
				this.txt_layer.color="#818181";
				this.txt_name.color="#818181";
			}
			else{
				var w=(info.rankValue/this._mgr.getPreMaxValue())*684;
				w=isNaN(w)?0:w;
				this.img_pro.width=w;
				this.txt_layer.text=!info.rankValue?Lang.str(1214):CommonUtil.numFormat((info.rankValue),1);
				this.txt_name.text=info.roleName;
				this.txt_layer.color="#d4e7f9";
				this.txt_name.color="#d4e7f9";
			}
		}
		else{
			var todayInfo=ele.getValue("curRank");
			if(todayInfo){
				w=(todayInfo.levelOrZhanli/this._mgr.getCurMaxValue())*684;
				w=isNaN(w)?0:w;
				this.img_pro.width=w;
				this.txt_layer.text=todayInfo.levelOrZhanli?CommonUtil.numFormat((todayInfo.levelOrZhanli),1):Lang.str(1214);
				this.txt_name.text=todayInfo.roleName;
				this.txt_layer.color="#d4e7f9";
				this.txt_name.color="#d4e7f9";
			}
			else{
				cfg=ele.getCfgData();
				limit=parseInt(cfg.limit);
				this.txt_layer.text=limit? CommonUtil.numFormat(limit,1)+Lang.str(976):Lang.str(428);
				this.txt_name.text=Lang.str(394);
				this.txt_layer.color="#818181";
				this.txt_name.color="#818181";
			}
		}
	});

	return HancockRankItem;
})(CommonRankItemUI)


