var LianDanItem=(function(_super){
	function LianDanItem(){
		this._mgr=null;
		this._vo=null;
		this._item=null;
		this._time=0;
		LianDanItem.__super.call(this);
	}

	__class(LianDanItem,'view.modules.lianDanLu.LianDanItem',_super);
	var __proto=LianDanItem.prototype;
	__proto.initialize=function(){
		this.btn_del.on("click",this,this.onDel);
		this.box_add.on("click",this,this.onLianDan);
		this._mgr=Mgr.lianDanLuM;
		this.txt_adddesc.style.align="center";
	}

	__proto.startTimer=function(){
		Laya.timer.loop(1000,this,this.onCd);
		this.onCd();
	}

	__proto.stopTimer=function(){
		Laya.timer.clear(this,this.onCd);
	}

	__proto.onCd=function(){
		var curPro=this._vo.curTimePro;
		if(curPro>=(this._time*1000)){
			this.stopTimer();
			return;
		}
		this.pro.value=curPro/(this._time*1000);
		this.txt_singlepro.text=Math.floor(curPro/1000)+"/"+this._time;
		var sp=this._mgr.getCurSpeed(this._vo.type,this._vo.deviceId);
		this.txt_time.changeText(CommonUtil.formatDate(((this._time-(curPro/1000))/sp)*1000,4,false));
	}

	__proto.onDel=function(){
		if(!this._vo)return;
		Mgr.lianDanLuA.sendCancelProduce(this._vo.type,this._vo.deviceId,this._vo.index);
	}

	__proto.onLianDan=function(){
		UIMgr.ins.openView(LianDanFormulaView,2);
	}

	__proto.dispose=function(){
		this.stopTimer();
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value){
			this.box_info.visible=false;
			this.txt_adddesc.innerHTML=CodeMgr.ins.getStringByCode([261236]);
			this.box_add.visible=true;
			return;
		}
		this.box_info.visible=true;
		this.box_add.visible=false;
		this._vo=value;
		var type=this._vo.type;
		var id=this._vo.proId;
		var ele=this._mgr.getFormulaByTypeAndId(type,id);
		if(!ele)return;
		var cfg=ele.getCfgData();
		this._time=parseInt(cfg.time)
		this.txt_danyaoname.text=cfg.name;
		if(!this._item){
			this._item=new ItemDisplayList();
			this.sp_reward.addChild(this._item);
		}
		this._item.showItems([cfg.reward]);
		this.txt_allpro.text=(this._vo.allNum-this._vo.subNum)+"/"+this._vo.allNum;
		if(this._vo.isProducing){
			this.btn_del.visible=false;
			this.txt_lianzhizhong.visible=true;
			this.pro.visible=true;
			this.txt_singlepro.visible=true;
			this.startTimer();
		}
		else{
			this.pro.visible=false;
			this.txt_singlepro.visible=false;
			this.pro.value=0;
			this.txt_singlepro.changeText(0+"/"+this._time);
			this.txt_time.text=CommonUtil.formatDate((this._time)*1000,4,false);
			this.btn_del.visible=true;
			this.txt_lianzhizhong.visible=false;
			this.stopTimer();
		}
	});

	return LianDanItem;
})(LianDanItemUI)


