			if(!ring)return;
			var viw=UIMgr.ins.openView(MarriageRingTip,2);
			var vo=new MarriageRingShowVo();
			vo.checkName=NetMgr.ins().roleVO.name;
			var cp=this._mgr.model.marryInfo.partarner;
			vo.cpName=cp?cp.roleName:"";
			vo.ringId=ring?ring.ringId:"";
			vo.ringLv=ring?ring.ringLevel:0;
