//class view.modules.zhanDuiJingJi.XiaYiZhanChangAttackItem extends ui.modules.bossHall.tequanBoss.TequanBossTrackMenuItemUI
var XiaYiZhanChangAttackItem=(function(_super){
	function XiaYiZhanChangAttackItem(){
		this._sdBossM=null;
		/**数据源*/
		this._ele=null;
		/**后端数据*/
		this._refreshTime=NaN;
		/**表数据*/
		this._cof=null;
		/**复活倒计时*/
		this.rtime=NaN;
		this.monster=null;
		this.role=null;
		XiaYiZhanChangAttackItem.__super.call(this);
		this._sdBossM=Mgr.shendianBossM;
	}

	__class(XiaYiZhanChangAttackItem,'view.modules.zhanDuiJingJi.XiaYiZhanChangAttackItem',_super);
	var __proto=XiaYiZhanChangAttackItem.prototype;
	__proto.initialize=function(){
		this.on("click",this,this.onSearch);
	}

	//开始倒计时
	__proto.ticktick=function(){
		if(this.rtime >0){
			this.txt_time.text=CommonUtil.formatDate(this.rtime,19,false);
			this.txt_time.color="#FF0000";
			}else{
			Laya.timer.clear(this,this.ticktick);
			this.txt_time.color="#77f440";
			this.txt_time.text=Lang.str(596);
			EventCenter.instance.event("updataxiayizhanchangattack");
		}
		this.rtime=this._refreshTime-Browser.now();
	}

	__proto.onSearch=function(){
		if((this._dataSource instanceof com.xq.proto.gen.zhanduipvp.ZhanDuiPVPMonsterInfo )){
			var arr=Mgr.xiaYiZhanChangMgr.getMonsterPosById(this.monster.monsterId);
			if(!arr)return;
			var pointArr=SceneContainer.GridToGlobal(arr[0],arr[1]);
			AIController.ins().startAutoPath(NetMgr.ins().roleVO.mapId,pointArr[0],pointArr[1],Handler.create(this,this.moveComplete));
			}else{
			if(Mgr.xiaYiZhanChangMgr.checkIsSafetyLayer()){
				Mgr.prompt.optionPrompt(Lang.str(1854));
				return;
			}
			if(Mgr.zhanduiM.checkIsSameTeam(this.role.roleId)){
				Mgr.prompt.optionPrompt(Lang.str(1855));
				}else{
				AIController.ins().startAutoCombat();
				AIController.ins().changeTarget(UnitManager.ins.getPlayerByRoleID(this.role.roleId));
				EventCenter.instance.event("boss_update_attackPlayer");
			}
		}
	}

	__proto.moveComplete=function(){
		AIController.ins().startAutoCombat();
	}

	__proto.gc=function(){
		Laya.timer.clear(this,this.ticktick);
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		this._dataSource=value;
		if((value instanceof com.xq.proto.gen.zhanduipvp.ZhanDuiPVPMonsterInfo )){
			this.monster=value;
			this._cof=Mgr.jindi.getMonsterById(this.monster.monsterId);
			this.txt_name.text=this._cof.name;
			this._refreshTime=this.monster.reviveTime;
			if(this._refreshTime){
				this.gc();
				this.rtime=this._refreshTime-Mgr.curTime.serverTimer;
				if(this.rtime>0){
					this.txt_time.color="#FF0000";
					this.txt_time.text=CommonUtil.formatDate(this.rtime,19,false);
					Laya.timer.loop(1000,this,this.ticktick);
					}else{
					this.txt_time.color="#77f440";
					this.txt_time.text=Lang.str(596);
				}
			}
			else{
				this.txt_time.color="#77f440";
				this.txt_time.text=Lang.str(596);
			}
			}else{
			this.role=value;
			this.txt_name.text=this.role.roleName;
			this.txt_time.text=this.role.score+"";
			var fight=NetMgr.ins().roleVO.fightValue;
			if(fight > this.role.fight *1.2){
				this.txt_name.color="#4dff55";
				this.txt_time.color="#4dff55";
				}else if(fight *1.2 < this.role.fight){
				this.txt_name.color="#ff4141";
				this.txt_time.color="#ff4141";
				}else{
				this.txt_name.color="#d4e7f9";
				this.txt_time.color="#d4e7f9";
			}
		}
		this._dataSource=value;
		this.txt_lv.text="";
	});

	return XiaYiZhanChangAttackItem;
})(TequanBossTrackMenuItemUI)


