		laya.ui.Component.prototype.initialize.call(this);
		this.img_icon1.skin=PathDefine.getMoneyIcon(13);
		this.img_icon2.skin=PathDefine.getMoneyIcon(2);
		CommonUtil.listSetScroll(this.goodList,false);
