//class view.modules.pvpcopy.douzhanfengshen.DWView extends ui.modules.pvpCopy.DouZhanFengShen.DWViewUI
var DWView=(function(_super){
	function DWView(){
		/**需要星*/
		this.needX=0;
		/**当前段*/
		this.cS=0;
		/**当前阶*/
		this.cL=0;
		/**当前星*/
		this.cX=0;
		DWView.__super.call(this);
	}

	__class(DWView,'view.modules.pvpcopy.douzhanfengshen.DWView',_super);
	var __proto=DWView.prototype;
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
		this.mouseEnabled=false;
		this.mouseThrough=true;
	}

	/**动态*/
	__proto.show2=function(nS,nL,nX,needX){
		if(nS !=this.cS)
			this.changeStage(nS,nL,nX,needX);
		else if(nL !=this.cL)
		this.changeLv(nL,nX,needX);
		else if(nX !=this.cX)
		this.changeStar(nX,needX);
	}

	__proto.changeStage=function(nS,nL,nX,needX){
		if(nS > this.cS){
			this.changeStar(this.needX,this.needX);
			var time=(this.needX-this.cX)*300+600;
			Tween.to(this.tlv,{x:this.tlv.x-200,alpha:0},300,null,null,time);
		}
		else{
			this.changeStar(0,this.needX);
			time=this.cX*300+600;
			Tween.to(this.tlv,{x:this.tlv.x+200,alpha:0},300,null,null,time);
		}
		this.needX=needX;
		this.cL=nL;
		Tween.to(this.bg,{scaleX:0},500,null,Handler.create(this,this.changeStage1,[nS,nX]),time);
	}

	__proto.changeStage1=function(nS,nX){
		if(nS > this.cS){
			this.tlv.x+=400;
			this.tlv.value=this.cL+Lang.str(251);
			Tween.to(this.tlv,{x:this.tlv.x-200,alpha:1},300,null,null);
			this.showStar(0,this.needX);
		}
		else{
			this.tlv.x-=400;
			this.tlv.value=this.cL+Lang.str(251);
			Tween.to(this.tlv,{x:this.tlv.x+200,alpha:1},300,null,null);
			this.showStar(this.needX,this.needX);
		}
		this.dispose();
		this.bg.skin=PathDefine.RES2_ROOT+PathDefine.PVP_COPY+nS+".png";
		Tween.to(this.bg,{scaleX:1},500,null,Handler.create(this,this.changeStage2,[nX]));
	}

	__proto.changeStage2=function(nX){
		this.changeStar(nX,this.needX);
	}

	__proto.changeLv=function(nL,nX,needX){
		if(nL < this.cL){
			this.changeStar(needX,needX);
			var time=(needX-this.cX)*300+600;
			Laya.timer.once(time,this,this.changeLv1,[true,nX,needX]);
		}
		else if(nL > this.cL){
			this.changeStar(needX,needX);
			time=this.cX*300+100;
			Laya.timer.once(time,this,this.changeLv1,[false,nX,needX]);
		}
		this.cL=nL;
	}

	__proto.changeLv1=function(flag,nX,needX){
		if(flag){
			Tween.to(this.tlv,{x:this.tlv.x-200,alpha:0},300,null,Handler.create(this,this.changeLv2,[flag,nX,needX]));
		}
		else{
			Tween.to(this.tlv,{x:this.tlv.x+200,alpha:0},300,null,Handler.create(this,this.changeLv2,[flag,nX,needX]));
		}
	}

	__proto.changeLv2=function(flag,nX,needX){
		this.tlv.value=this.cL+Lang.str(251);
		if(flag){
			this.tlv.x+=400;
			Tween.to(this.tlv,{x:this.tlv.x-200,alpha:1},300,null,null);
			this.showStar(0,needX);
		}
		else{
			this.tlv.x-=400;
			Tween.to(this.tlv,{x:this.tlv.x+200,alpha:1},300,null,null);
			this.showStar(0,needX);
		}
		Laya.timer.once(300,this,this.changeStar,[nX,needX]);
	}

	__proto.changeStar=function(nX,needX){
		var flag=false;
		if(nX>=this.cX){
			var c=this.cX;
			var n=nX;
			var idx=0;
			flag=true;
		}
		else{
			c=nX;
			n=this.cX;
			idx=n-c;
			flag=false;
		}
		if(needX %2==0){
			for(var i=c;i < n;i++){
				var s=this["xo"+i];
				s.visible=true;
				if(flag){
					var x1=s.x;
					var y1=s.y;
					s.x-=(s.width<<1);
					s.y-=(s.height<<1);
					s.scaleX=6;
					s.scaleY=6;
					s.alpha=0;
					Tween.to(s,{x:x1,y:y1,alpha:1,scaleX:1,scaleY:1},600,Ease.backInOut,null,idx*300);
					idx++;
				}
				else{
					x1=s.x-(s.width<<1);
					y1=s.y-(s.height<<1);
					s.alpha=1;
					Tween.to(s,{x:x1,y:y1,alpha:0,scaleX:6,scaleY:6},600,Ease.backInOut,Handler.create(this,this.resetStar,[s]),idx*300);
					idx--;
				}
			}
		}
		else{
			var off=(needX-5)>>1;
			for(i=c-off;i < n-off;i++){
				s=this["x"+i];
				s.visible=true;
				if(flag){
					x1=s.x;
					y1=s.y;
					s.x-=(s.width<<1);
					s.y-=(s.height<<1);
					s.scaleX=6;
					s.scaleY=6;
					s.alpha=0;
					Tween.to(s,{x:x1,y:y1,alpha:1,scaleX:1,scaleY:1},600,Ease.backInOut,null,idx*300);
					idx++;
				}
				else{
					x1=s.x-(s.width<<1);
					y1=s.y-(s.height<<1);
					s.alpha=1;
					Tween.to(s,{x:x1,y:y1,alpha:0,scaleX:6,scaleY:6},600,Ease.backInOut,Handler.create(this,this.resetStar,[s]),idx*300);
					idx--;
				}
			}
		}
		this.cX=nX;
		this.needX=needX;
	}

	__proto.resetStar=function(s){
		s.visible=false;
		s.x+=(s.width<<1);
		s.y+=(s.height<<1);
		s.scaleX=1;
		s.scaleY=1;
		s.alpha=1;
	}

	/**静态*/
	__proto.show1=function(curStage,curLv,curX,needX){
		if(this.cS !=curStage)
			this.dispose();
		CommonUtil.reloadImg(this.bg);
		this.cS=curStage;
		this.cL=curLv;
		this.cX=curX;
		needX=needX;
		this.tlv.value=this.cL+Lang.str(251);
		this.bg.skin=PathDefine.RES2_ROOT+PathDefine.PVP_COPY+curStage+".png";
		this.showStar(this.cX,needX);
	}

	__proto.showStar=function(curX,needX){
		for(var i=0;i< 5;i++){
			this["xb"+i].visible=false;
			this["x"+i].visible=false;
			if(i<4){
				this["xbo"+i].visible=false;
				this["xo"+i].visible=false;
			}
		}
		if(needX %2==0){
			for(i=0;i < needX;i++)
			this["xbo"+i].visible=true;
			for(i=0;i < curX;i++)
			this["xo"+i].visible=true;
		}
		else{
			var off=(needX-5)>>1;
			for(i=0-off;i < 5+off;i++)
			this["xb"+i].visible=true;
			for(i=0-off;i < curX-off;i++)
			this["x"+i].visible=true;
		}
		this.cX=curX;
		this.needX=needX;
	}

	__proto.dispose=function(){
		Laya.loader.clearRes(this.bg.skin);
		this.bg.skin=null;
	}

	return DWView;
})(DWViewUI)


