	__proto.refreshSelect=function(){
		var len=this.cfgArr.length;
		var isHaveRedPoint=false;
		for (var i=0;i < len;i++){
			var rankCfg=this.cfgArr[i];
			if(this.redVo.getCornerState(rankCfg.type)){
				if(this.isEndAllMoBai){
					this.naviTab.selectedIndex=rankCfg.order-1;
					this.naviTab.tweenTo(rankCfg.order-1);
				}
				isHaveRedPoint=true;
				if(!this.isEndAllMoBai){
					this._curAllJYRankType=parseInt(rankCfg.type);
					Laya.timer.once(800,this,this.MobaiFun);
				}
				break ;
			}
		}
		if(!isHaveRedPoint&&!this.isEndAllMoBai){
			this.isEndAllMoBai=true;
			this._curAllJYRankType=-1;
		}
	}

