var SettingView=(function(_super){
	function SettingView(){
		this.setMgr=null;
		this.roleVo=null;
		/**当前背景音大小*/
		this.curBgm=NaN;
		/**当前音效大小*/
		this.curSound=NaN;
		this.cbArr=null;
		this.quaArr=null;
		this.selectQuaLv=0;
		this.privacyView=null;
		SettingView.__super.call(this);
		this.name="SettingView";
	}

	__class(SettingView,'view.modules.setting.SettingView',_super);
	var __proto=SettingView.prototype;
	__proto.initialize=function(){
		laya.ui.Component.prototype.initialize.call(this);
		this.setMgr=Mgr.setting;
		this.roleVo=NetMgr.ins().roleVO;
		this.txt_ver.text=Main.VER;
		this.ckAuto.on("click",this,this.optionalAuto);
		this.ckMusic.on("click",this,this.optionalMusic);
		this.gameMusic.on("click",this,this.optionalGameMusic);
		this.ckShenQing.on("click",this,this.optionalShenQing);
		this.ckZhenPing.on("click",this,this.optionalZhenPing);
		this.ckSkillTip.on("click",this,this.optionalSkillTip);
		this.btn_help.on("click",this,this.onQieHuang);
		this.btn_help.visible=Configs.isShowQHBtn;
		this.setupSlider();
		this.checkbox_subplayer.visible=true;
		this.checkbox_subplayer.on("click",this,this.onSubplayerName);
		this.ckMonster.on("click",this,this.optionalMonster);
		this.ckPlayer.on("click",this,this.optionalPlayer);
		this.cbArr=[this.cb_lc,this.cb_ph,this.cb_jz];
		this.quaArr=[PictureQualityLevel.Low,PictureQualityLevel.Middle,PictureQualityLevel.High];
		this.cb_jz.on("click",this,this.onSelectQua,[3]);
		this.cb_ph.on("click",this,this.onSelectQua,[2]);
		this.cb_lc.on("click",this,this.onSelectQua,[1]);
		if(this.box_user){
			var boxW=369;
			if(Configs.userArgeementPath){
				this.txt_user.visible=true;
				this.txt_user.on("click",this,this.onUserTip);
			}
			else{
				this.txt_user.visible=false;
				boxW-=96;
			}
			if(Configs.yinsiInfoPath){
				this.txt_privacy1.visible=true;
				this.txt_privacy1.on("click",this,this.onPrivacy);
				this.txt_privacy1.x=this.txt_user.visible?113:0;
				this.txt_privacy2.visible=true;
				this.txt_privacy2.on("click",this,this.onPrivacy);
				this.txt_privacy2.x=this.txt_user.visible?225:113;
			}
			else{
				this.txt_privacy1.visible=false;
				this.txt_privacy2.visible=false;
				boxW-=192;
			}
			this.box_user.width=boxW;
			this.box_user.x=(this.width-boxW)/2;
		}
	}

	__proto.optionalAuto=function(){
		this.setMgr.isAutoUseNuqi=this.ckAuto.selected;
	}

	__proto.optionalMonster=function(){
		this.setMgr.isShieldMonster=this.ckMonster.selected;
		UnitManager.ins.shieldUnit(3,this.ckMonster.selected);
	}

	__proto.optionalPlayer=function(){
		this.setMgr.isShieldOtherPlayer=this.ckPlayer.selected;
		UnitManager.ins.shieldUnit(0,this.ckPlayer.selected);
	}

	__proto.optionalMusic=function(){
		this.setMgr.isBgBGM=!this.ckMusic.selected;
		this.hslider_bgm.disabled=!this.setMgr.isBgBGM;
	}

	__proto.optionalGameMusic=function(){
		this.setMgr.isBgSound=!this.gameMusic.selected;
		this.hslider_sound.disabled=!this.setMgr.isBgSound;
	}

	__proto.optionalShenQing=function(){
		this.setMgr.isShowShenQing=!this.ckShenQing.selected;
	}

	__proto.optionalZhenPing=function(){
		this.setMgr.isShowZhenPing=!this.ckZhenPing.selected;
	}

	__proto.optionalSkillTip=function(){
		this.setMgr.isPermitSuperSkillTip=this.ckSkillTip.selected;
	}

	__proto.onQieHuang=function(){
		ReconnectAction.getInstance().restart();
	}

	// }
	__proto.onSubplayerName=function(){
		var forbit=this.checkbox_subplayer.selected;
		this.setMgr.isForbitSubplayerName=forbit;
		UnitManager.ins.sheildSubplayerName(!forbit);
	}

	__proto.onSelectQua=function(index){
		for(var i=0;i<3;i++){
			this.cbArr[i]&&(this.cbArr[i].selected=index==(i+1));
		}
		this.selectQuaLv=index;
	}

	__proto.dispose=function(){
		this.setMgr.sendSetSettingParams();
		this.setVolume();
		this.setSubplayerName();
		this.setPicQua();
	}

	__proto.setSubplayerName=function(){
		var value=this.setMgr.isForbitSubplayerName?1:0;
		Mgr.comonp.setCustomData(5,value.toString());
	}

	/**记录画质*/
	__proto.setPicQua=function(){
		PathDefine.setQualityLevel(this.selectQuaLv);
		LocalStorage.setItem("picQua",this.selectQuaLv.toString());
	}

	__proto.setVolume=function(){
		Mgr.comonp.setCustomData(2,this.setMgr.bgm.toString());
		Mgr.comonp.setCustomData(3,this.setMgr.soundEffect.toString());
	}

	__proto.open=function(){
		this.ckZhenPing.selected=!this.setMgr.isShowZhenPing;
		this.ckShenQing.selected=!this.setMgr.isShowShenQing;
		this.ckMusic.selected=!this.setMgr.isBgBGM;
		this.gameMusic.selected=!this.setMgr.isBgSound;
		this.ckPlayer.selected=this.setMgr.isShieldOtherPlayer;
		this.ckMonster.selected=this.setMgr.isShieldMonster;
		this.ckAuto.selected=this.setMgr.isAutoUseNuqi;
		this.ckSkillTip.selected=this.setMgr.isPermitSuperSkillTip;
		this.updateSound();
		this.setupPicQua();
		this.checkbox_subplayer.selected=this.setMgr.isForbitSubplayerName;
		GuideTargetMgr.ins.changeGuideView(this);
		if(this.box_user){
			this.box_user.visible=Configs.showPrivacyInGame;
		}
	}

	//游戏内设置界面是否显示用户协议
	__proto.setupPicQua=function(){
		this.selectQuaLv=PathDefine.QUALITY;
		if(this.selectQuaLv<=0)this.selectQuaLv=2;
		for(var i=0;i<3;i++){
			this.cbArr[i]&&(this.cbArr[i].selected=(i+1)==this.selectQuaLv);
		}
	}

	__proto.setupSlider=function(){
		this.hslider_bgm.setSlider(0,1,0);
		this.hslider_bgm.tick=0.01;
		this.hslider_sound.setSlider(0,1,0);
		this.hslider_sound.tick=0.01;
		this.hslider_bgm.changeHandler=Handler.create(this,this.bgmChange,null,false);
		this.hslider_sound.changeHandler=Handler.create(this,this.soundChange,null,false);
		this.hslider_bgm.showLabel=false;
		this.hslider_sound.showLabel=false;
	}

	__proto.updateSound=function(){
		this.curBgm=this.setMgr.bgm;
		this.curBgm=isNaN(this.curBgm)?0.6:this.curBgm;
		this.hslider_bgm.value=this.curBgm;
		this.curSound=this.setMgr.soundEffect;
		this.curSound=isNaN(this.curSound)?0.6:this.curSound;
		this.hslider_sound.value=this.curSound;
		this.hslider_bgm.disabled=!this.setMgr.isBgBGM;
		this.hslider_sound.disabled=!this.setMgr.isBgSound;
	}

	__proto.bgmChange=function(num){
		this.curBgm=num;
		this.setMgr.bgm=this.curBgm;
	}

	__proto.soundChange=function(num){
		this.curSound=num;
		this.setMgr.soundEffect=this.curSound;
	}

	__proto.onUserTip=function(){
		Mgr.noticeMgr.privacySelectIndex=0;
		this.popTip();
	}

	__proto.onPrivacy=function(){
		Mgr.noticeMgr.privacySelectIndex=Configs.userArgeementPath?1:0;
		this.popTip();
	}

	__proto.popTip=function(){
		if(!this.privacyView){
			this.privacyView=new PrivacyDialog();
		}
		this.privacyView.visible=true;
		this.privacyView.popup();
	}

	return SettingView;
})(SettingViewUI)


