//class view.modules.share.ShareTaskRender extends ui.modules.share.ShareTaskRenderUI
var ShareTaskRender=(function(_super){
	function ShareTaskRender(){
		this._info=null;
		this._ele=null;
		this._itemDis=null;
		ShareTaskRender.__super.call(this);
		this.btn_lq.on("click",this,this.onLqReward);
	}

	__class(ShareTaskRender,'view.modules.share.ShareTaskRender',_super);
	var __proto=ShareTaskRender.prototype;
	__proto.showAni=function(){
		this.btn_lq.showAni("anniu_01",-4,-2);
	}

	__proto.onLqReward=function(){
		if(!this._info||this._info.state)return;
		var cfg=this._ele.getCfgData();
		var taskId=parseInt(cfg.id);
		var type=parseInt(cfg.type);
		if(this.btn_lq.label==Lang.str(387)){
			this.sendSdkFun(type);
			return;
		}
		Mgr.shareTaskA.sendTaskLqInfo(taskId);
		this._itemDis.fly();
	}

	__proto.sendSdkFun=function(type){
		var pro=this._info.process+1;
		var hand=Handler.create(Mgr.shareTaskA,Mgr.shareTaskA.sendTaskProcess,[type,pro]);
		switch(type){
			case 1:{
					BaseSDK.ins.sendGuanZhuYouLi(hand);
					break ;
				}
			case 2:{
					BaseSDK.ins.sendYaoQingYouLi(hand);
					break ;
				}
			case 3:{
					BaseSDK.ins.partnerVerifyState(hand);
					break ;
				}
			case 4:{
					BaseSDK.ins.installShortcut(hand);
					break ;
				}
			case 5:{
					BaseSDK.ins.addToFavorites(hand);
					break ;
				}
			case 6:{
					BaseSDK.ins.addColorSign(hand);
					break ;
				}
			case 7:{
					BaseSDK.ins.addRecentColorSign(hand);
					break ;
				}
			}
	}

	__proto.dispose=function(){
		this.btn_lq.dispose();
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		this._ele=value;
		this._info=this._ele.getValue("s_data");
		if(!this._info)return;
		var cfg=this._ele.getCfgData();
		var taskTimes=parseInt(cfg.times);
		this.btn_lq.visible=!this._info.state;
		this.img_ylq.visible=this._info.state;
		CornerUtil.removeCorner(this.btn_lq);
		this.btn_lq.dispose();
		this.txt_pro.text=this._info.process+"/"+taskTimes;
		this.txt_name.text=cfg.name;
		this.txt_count.text=cfg.times;
		this.txt_pro.color="#ff4141";
		this.btn_lq.label=Lang.str(1577);
		if(cfg.price){
			this.box_price.visible=true
			this.txt_desc.text=Lang.str(436)+cfg.price+Lang.str(404);
			}else{
			this.box_price.visible=false;
			this.txt_desc.text="";
		}
		if(this._info.process>=taskTimes){
			if(this.btn_lq.visible){
				CornerUtil.addCorner(this.btn_lq);
				this.showAni();
			}
			this.txt_pro.color="#4dff55";
			}else{
			this.showAni();
			this.btn_lq.label=Lang.str(387);
		}
		if(!this._itemDis){
			this._itemDis=new ItemDisplayList();
			this.sp_reward.addChild(this._itemDis);
		};
		var rewardArr=cfg.reward.split(";");
		this._itemDis.showItems(rewardArr,5,100);
		this.hbox.refresh();
	});

	return ShareTaskRender;
})(ShareTaskRenderUI)


