//class view.modules.skill.JueXueItem extends ui.modules.skill.JueXueItemUI
var JueXueItem=(function(_super){
	function JueXueItem(){
		JueXueItem.__super.call(this);
	}

	__class(JueXueItem,'view.modules.skill.JueXueItem',_super);
	var __proto=JueXueItem.prototype;
	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		this._dataSource=value;
		if(!value)
			return;
		var vo=value;
		var skVO=SkillManager.ins.getData(vo.skillId);
		if(skVO){
			this.skill.setSkillVo(skVO);
			var string="";
			this.txt_name.color="#ff4141";
			if(value.skillType=="1"){
				var skMsg=Mgr.wdMgr.getSkillMsg(vo.id);
				if(skMsg && skMsg.CanOrCant && skMsg.activeState==2){
					this.txt_name.color="#4dff55";
					this.txt_name.text=Lang.str(468);
					}else{
					this.txt_name.text=value.openCondition;
				}
				}else if(value.skillType=="2"){
				if(Mgr.fhMgr.getZhuanShengLv()>=parseInt(value.openCondition)){
					this.txt_name.color="#4dff55";
					this.txt_name.text=Lang.str(468);
					}else{
					this.txt_name.text=value.openConditionDes;
				}
				}else if(value.skillType=="3"){
				if(Mgr.fbgkMgr.maxId >=parseInt(value.openCondition)){
					this.txt_name.color="#4dff55";
					this.txt_name.text=Lang.str(468);
					}else{
					this.txt_name.text=value.openConditionDes;
				}
				}else if(value.skillType=="4"){
				if(Mgr.equip.hasEquip(1,parseInt(value.openCondition))){
					this.txt_name.color="#4dff55";
					this.txt_name.text=Lang.str(468);
					}else{
					this.txt_name.text=value.openConditionDes;
				}
				}else if(value.skillType=="5"){
				if(Mgr.zhanZhuangMgr.checkSuitActive(parseInt(value.openCondition))){
					this.txt_name.color="#4dff55";
					this.txt_name.text=Lang.str(468);
					}else{
					this.txt_name.text=value.openConditionDes;
				}
				}else if(value.skillType=="6"){
				if(Mgr.shenZhuMgr.getShenZhuSkillIsActive(value.skillId)){
					this.txt_name.color="#4dff55";
					this.txt_name.text=Lang.str(468);
					}else{
					this.txt_name.text=value.openConditionDes;
				}
			}
			this.txt_skillName.text=skVO.name;
			this.html_miaoshu.innerHTML=skVO.describe;
			}else{
			this.txt_name.text="";
			this.html_miaoshu.innerHTML="";
		}
	});

	return JueXueItem;
})(JueXueItemUI)


