var PurchaseTaskRender=(function(_super){
	function PurchaseTaskRender(){
		this._cfg=null;
		this._rewardItem=null;
		PurchaseTaskRender.__super.call(this);
		this.btn_lq.on("click",this,this.onClick);
	}

	__class(PurchaseTaskRender,'view.modules.unitaryPurchase.PurchaseTaskRender',_super);
	var __proto=PurchaseTaskRender.prototype;
	__proto.onClick=function(){
		if(this._cfg){
			if(this.btn_lq.label==Lang.str(362)){
				if(!Mgr.unitaryPurchaseM.isBuy){
					AlertUtil.ShowAlert("购买后可领取奖励，是否前往购买?",Handler.create(this,this.goBuy),null);
					return;
				};
				var id=parseInt(this._cfg.id);
				Mgr.unitaryPurchaseA.sendGetRewardInfo(id);
				this._rewardItem.fly();
				}else{
				Mgr.prompt.optionPrompt("条件未完成");
			}
		}
	}

	__proto.goBuy=function(){
		if(Configs.isOpenCZ){
			Mgr.chatPro.sendDebugMsg("@ add directrmb "+175);
		}
		else{
			Mgr.vip.sendJHSDKCharege(0,175,"");
		}
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		var ele=value;
		var info=ele.getValue("s_data");
		if(!info)return;
		this._cfg=ele.getCfgData();
		var val=parseInt(this._cfg.val);
		var reward=this._cfg.reward.split(";");
		var ifCanAddRedPoint=Mgr.unitaryPurchaseM.ifAddRedPoint(ele);
		this.txt_suffix.changeText("");
		this.txt_des.text=this._cfg.desc;
		this.txt_val.x=this.txt_des.x+this.txt_des.textField.textWidth;
		this.txt_val.text=CommonUtil.numFormat(val);
		this.txt_val.color=info.val>=val?"#4dff55":"#d4e7f9";
		this.img_ylq.visible=info.state;
		this.btn_lq.visible=!info.state;
		if(!this._rewardItem)this._rewardItem=new ItemDisplayList();
		this.sp_item.addChild(this._rewardItem);
		this._rewardItem.showItems(reward);
		CornerUtil.removeCorner(this.btn_lq);
		this.btn_lq.skin="modules/common/btn_orange.png";
		this.btn_lq.label=Lang.str(362);
		if(info.val<val){
			this.btn_lq.skin="modules/common/btn_black.png";
			this.btn_lq.label=Lang.str(1318);
		}
		if(ifCanAddRedPoint){
			CornerUtil.addCorner(this.btn_lq);
		}
		if(this._cfg.suffix){
			this.txt_suffix.x=this.txt_val.x+this.txt_val.textField.textWidth;
			this.txt_suffix.changeText(this._cfg.suffix);
		}
	});

	return PurchaseTaskRender;
})(PurchaseTaskRenderUI)


