	/**检查是否有之升丹*/
	__proto.checkNeedZS=function(){
		if(this.serverInfo && this.serverInfo.activeState){
			var vo=this.payMgr.getZSDan(this.curType,this.serverInfo.jieshu);
			if(vo){
				if(!this.zhiShengTip){
					this.zhiShengTip=new ZhiShengTips();
					this.addChild(this.zhiShengTip);
					this.zhiShengTip.pos(543,768);
				}
				if(!this.payMgr.checkHideTJ("Mount"+this.curType)){
					this.zhiShengTip.visible=true;
					this.zhiShengTip.dataSource=vo;
					this.floatTween=FloatTween.start(this.zhiShengTip,8,0.05,0);
					this.zhiShengTip.on("TeJiaTipsClose",this,this.closeTeJia);
					return;
				}
			}
		}
		if(this.zhiShengTip){
			this.zhiShengTip.visible=false;
			if(this.floatTween){
				this.floatTween.stop();
			}
		}
	}

	__proto.closeTeJia=function(){
		this.zhiShengTip.visible=false;
		this.payMgr.addHideTJGoodsType("Lingqi"+this.curType);
	}

	/**是否展示解封*/
	__proto.checkJieFeng=function(){
		if(!this.serverInfo || !this.serverInfo.activeState){
			Mgr.payLinePro.reqActiveSystem(this.curType);
		}
	}

	/**获取最大阶数*/
	__proto.getMaxJie=function(){
		this.maxJie=this.cfgTable.getItemsByField("level",0).length;
	}

	__proto.updateGongMing=function(){
		return;
		var gmtabCfg=this.payMgr.getGMCfg(this.curType);
		var gmMsg=this.payMgr.getGMInfo(this.curType);
		if(gmMsg)
			var gmCfg=gmtabCfg.getItemByField("gongmingLevel",gmMsg.ActivedJieShu+1);
		else
		gmCfg=gmtabCfg.getItemByField("gongmingLevel",1);
		var tname=this.payMgr.getNameByType(this.curType);
		if(!gmMsg || (!gmCfg && gmMsg.ActivedJieShu <=0)){
			gmCfg=gmtabCfg.objectDataArray[0];
		}
	}

	__proto.flush=function(){
		var pydata=this.payMgr.model.curModel;
		this.serverInfo=pydata.myPayLineInfo[this.curType];
		if(!this.serverInfo || !this.serverInfo.activeState){
			return;
		}
		this.updataFight();
		this.showStar(this.serverInfo.stars);
		this.curJie=this.serverInfo.jieshu;
		var lv=pydata.getPeiYangLevel(this.curType);
		this.txt_lv.text=lv+Lang.str(251);
		this.box_jie.visible=(lv >0);
		this.curAniStep=this.curJie;
		this.updateSkill();
		this.updateAni();
		this.onRefreshAttr();
		this.freshProValue();
		var maxJ=this.payMgr.getMaxJie(this.curType);
		if(this.curJie > 1 && this.serverInfo.jieshu==maxJ){
			this.maxLbl.visible=true;
			this.jjBox.visible=false;
			if(this.matCell)
				this.matCell.visible=false;
		}
		else{
			this.pro.visible=true;
			this.jjBox.visible=true;
			if(this.matCell)
				this.matCell.visible=true;
			this.maxLbl.visible=false;
			this.listAttribute.x=172;
		}
		if(this.isUM){
			this.updateMaterial();
			this.isUM=false;
		}
	}

	__proto.updateAni=function(){
		if(!this.aniUrlH)return;
		if(!this.huanhuaUrl){
			this.mountAni1.scaleX=parseFloat(this.curCfgInfo.size);
			this.mountAni1.scaleY=parseFloat(this.curCfgInfo.size);
			this.mountAni1.setRes(this.aniUrlH+this.curCfgInfo["uires"]+"/"+this.curCfgInfo["uires"]+this.aniUrlE);
		}
		else{
			this.mountAni1.scaleX=this.huanhuaSca;
			this.mountAni1.scaleY=this.huanhuaSca;
			this.mountAni1.setRes(this.huanhuaUrl);
		}
	}

	/**刷新属性*/
	__proto.onRefreshAttr=function(){
		if(this.curStarNum==this.serverInfo.stars)
			return;
		this.curStarNum=this.serverInfo.stars;
		var curOb=this.getCachCfg(this.serverInfo.jieshu,this.serverInfo.stars);
		if(this.serverInfo.stars >=9)
			var nextJ=this.getCachCfg(this.serverInfo.jieshu+1,0);
		else
		nextJ=this.getCachCfg(this.serverInfo.jieshu,this.serverInfo.stars+1);
		var curAttrArr=CommonUtil.getListAryByCfg(curOb);
		if(!nextJ){
			var attrArr=CommonUtil.getListAryByCfg(curOb,"","#d4e7f9",false,1,false);
			var nextAttrArr=CommonUtil.getListAryByCfg(curOb,"","#d4e7f9",false);
			}else{
			if(this.serverInfo.jieshu==1 && this.serverInfo.stars==0){
				attrArr=CommonUtil.getListAryByCfg(nextJ,"","#d4e7f9",false,1,false);
				nextAttrArr=CommonUtil.getListAryByCfg(nextJ,"","#d4e7f9",false);
				}else{
				attrArr=CommonUtil.getListAryByCfg(curOb,"","#d4e7f9",false);
				nextAttrArr=CommonUtil.getListAryByCfg(nextJ,"","#d4e7f9",false);
			}
		}
		CommonUtil.mergeCalcAdd(attrArr,nextAttrArr);
		this.listAttribute.array=attrArr;
		this.needView.setData(curOb.needitem);
	}

	/**更新进度条*/
	__proto.freshProValue=function(msg){
		if(msg){
			Mgr.prompt.playUIEffect("guangshu",this.spr_ani,0,30);
		}
		this.serverInfo=this.payMgr.model.curModel.myPayLineInfo[this.curType];
		var tempInfo=this.getCachCfg(this.serverInfo.jieshu,this.serverInfo.stars);
		if(tempInfo){
			if(msg && msg.type==this.curType){
				this.showParticleAni();
				var tluckyV=msg.luckyLevel;
				var tpV=msg.tempValue;
				if(this.payMgr.curPayLineJieShu < msg.jieshu){
					Mgr.payLinePro.sendGetPaylineInfo(this.curType);
					this.startMove(0,tempInfo["value"]);
					this.isUM=true;
					EventCenter.instance.event("UPGRADE_SUCCEST_PAYLINE",[this.curType]);
					return;
				}
				this.showStar(msg.stars);
				this.onRefreshAttr();
			}
			else{
				tluckyV=this.serverInfo.luckyValue;
				tpV=this.serverInfo.tempValue;
			}
			this.startMove(tluckyV,tempInfo["value"]);
			this.pro.value=tluckyV / tempInfo["value"];
		}
	}

	/**展示进阶特效*/
	__proto.showParticleAni=function(){
		var tmp;
		if(this.isSd){
			tmp=this.sdPo;
		}
		else{
			tmp=this.autoPo;
		}
		CommonAniUtil.ins.particleAni(3,tmp,this.edPo,30,30);
	}

