		this.img_svipbg.visible=index<=Mgr.vipcfgMgr.minStarLv;
		this.img_xy.visible=index>Mgr.vipcfgMgr.minStarLv;
		if(index>Mgr.vipcfgMgr.minStarLv){
			this.fontclip_nextlv.x=1001;
			this.img_xy.x=1000;
			this.fontclip_vip.pos(7,150);
			}else{
			this.fontclip_vip.pos(2,136);
			this.fontclip_nextlv.x=1000;
			this.img_xy.x=1001;
		}
		if(index < Mgr.vipcfgMgr.maxSvipLv){
			index=index+1;
		};
		var arr=this.table.getAllItemByFiled("lv",index);
