	var __proto=JianZhengTaskItem.prototype;
	__proto.onClick=function(){
		if(!this.cfg){
			return
		}
		if(this.btnlq.label==Lang.str(411)){
			UIMgr.ins.navigateToViewByID(this.cfg.panelId);
			if(Mgr.xinWu.curType==0){
				UIMgr.ins.closeView(MarriageJzTask);
			}
			else{
				UIMgr.ins.closeView(QiLingBiJzTask);
			}
		}
		else{
			Mgr.xinWuAct.reqTaskReward(Mgr.xinWu.curType,this.cfg.Id);
		}
	}

