	__proto.rewardView=function(){
		var tempAry=this.mgr.rewardList;
		if(!tempAry)
			return;
		var rewar_dj=[];
		var len=tempAry.length;
		for (var i=0;i < len;i++){
			var itemPa=tempAry[i];
			rewar_dj.push(itemPa.templateId+":"+itemPa.count);
		}
		if(len>1){
			var v=UIMgr.ins.openView(XunbaoRewarView,2);
			var obj={};
			obj["rewarArr"]=rewar_dj;
			obj["type"]=Mgr.csxbMgr.BASETYPE_MG;
			v.dataSource=obj;
		}
		else{
			if(!this._singleItem)this._singleItem=new ItemDisplayList();
			this.sp_single.addChild(this._singleItem);
			this._singleItem.setTeXiao(true);
			this._singleItem.showItems(rewar_dj,5,183,100,1);
			this._singleItem.fly(null,new Point(340,1090));
			this._singleItem.clear();
		};
		var arrZf=this.mgr.zhuFuZhiList;
		if(arrZf && arrZf.length > 0){
			var xbdj=UIMgr.ins.openView(XunbaoDaJiagnView,2);
			xbdj.dataSource={"rewardArr":[arrZf[0]]};
		}
	}

