	// }
	__proto.teShuJiagli=function(){
		this.removeArray();
		if(this.dj1_srr){
			var leng=this.dj1_srr.length;
			for (var k=0;k < leng;k++){
				this.dj1_srr[k].removeSelf();
			}
			this.dj1_srr.length=0;
			var leng_=this.dj2_srr.length;
			for (var y=0;y < leng_;y++){
				this.dj2_srr[y].removeSelf();
			}
			this.dj2_srr.length=0;
		};
		var len=this.itemdata.length;
		var dj=[];
		var index=0;
		for (var i=0;i < len;i++){
			var itemData=this.itemdata[i];
			if(itemData && itemData.layer >=1){
				var showItem=itemData.showitem;
				if(!showItem)continue ;
				var item=showItem.split(":");
				var vo=Mgr.item.getItemVO(item[0]);
				var cell=new BagItemFactoryView();
				vo.count=item[1];
				vo.isShowName=true;
				cell.dataSource=vo;
				this.sprite1.addChild(cell);
				if(itemData.layer==1){
					cell.x=((cell.width+this._offset)*i)+30;
					cell.y=0;
					index=itemData.ID;
					this.dj1_srr.push(cell);
					}else if(itemData.layer==2){
					cell.x=((cell.width+this._offset)*(i-index))+30;
					cell.y=125;
					this.dj2_srr.push(cell);
				}
			}
			if(itemData.maxgod==1){
				dj.push(itemData.showitem);
			}
		}
		this.teShuItem=new ItemDisplayList();
		this.sprite2.addChild(this.teShuItem);
		this.teShuItem.setTeXiao(true);
		this.teShuItem.showItems(dj,5,183,100,1.2);
		var len_=this.box_name.length;
		for (var j=0;j < len_;j++){
			showItem=dj[j];
			if(showItem){
				var a=showItem.split(":");
				if(a){
					var needItemVO=Mgr.item.getItemVO(a[0]);
					this.box_name[j].text=needItemVO.goodName;
				}
			}
		}
		Laya.timer.loop(50,this,this.yiDong);
	}

	__proto.yiDong=function(){
		var len=this.dj1_srr.length;
		for (var i=0;i < len;i++){
			var item=this.dj1_srr[i];
			item.x=item.x-3;
			if(item.x <=-item.width){
				item.x=this.dj1_srr[len-1].x+item.width+this._offset
				this.dj1_srr.push(item);
				this.dj1_srr.splice(i,1);
			}
		};
		var len_=this.dj2_srr.length;
		for (var j=0;j < len_;j++){
			var item_=this.dj2_srr[j];
			item_.x=item_.x-3;
			if(item_.x <=-item_.width){
				item_.x=this.dj2_srr[len_-1].x+item_.width+this._offset
				this.dj2_srr.push(item_);
				this.dj2_srr.splice(j,1);
			}
		}
	}

	__proto.mianFeiCiShu=function(){
		this.tidaiMt=this.mgr.getTidaiMt(this.type);
		this.tidaiMtTen=this.mgr.gettidaiMtTen(this.type);
		this.tidaiMtFifty=this.mgr.gettidaiMtFifty(this.type);
		if(this.mgr.mfCiShu > 0){
			this.txt_mf.color="#4dff55";
			this.btn_xunbao1.showAni("anniu_01",-4,-2);
			this.btn_xunbao1.label=Lang.str(1739);
		}
		else{
			this.txt_mf.color="#ff4141";
			this.btn_xunbao1.dispose();
			this.btn_xunbao1.label=Lang.str(1740);
		}
		this.txt_mf.text=this.mgr.mfCiShu+"/"+this.mgr.frerMaxNum;
		var id=this.tidaiMtTen[0];
		var montype=Mgr.moneyMgr.getMoneyTypeById(id);
		if(montype){
			var djsl=Mgr.moneyMgr.getMoneyByType(montype);
		}
		else{
			djsl=Mgr.bag.getBagMatCount(this.tidaiMtTen[0]);
		};
		var countStr=CommonUtil.numFormat(djsl);
		this.txt_xunbao1.text=countStr+"/"+this.tidaiMt[1];
		this.txt_xunbao2.text=countStr+"/"+this.tidaiMtTen[1];
		this.txt_xunbao3.text=countStr+"/"+this.tidaiMtFifty[1];
		CornerUtil.removeCorner(this.btn_xunbao1);
		CornerUtil.removeCorner(this.btn_xunbao2);
		CornerUtil.removeCorner(this.btn_xunbao3);
		if(djsl >=this.tidaiMt[1]|| this.mgr.mfCiShu >0){
			if(this.type==108){
				CornerUtil.addCorner(this.btn_xunbao1);
			}
			else{
				CornerUtil.addCorner(this.btn_xunbao1);
			}
		}
		if(djsl >=this.tidaiMtTen[1]){
			if(this.type==108){
				CornerUtil.addCorner(this.btn_xunbao2,0,-10);
			}
			else{
				CornerUtil.addCorner(this.btn_xunbao2,0,-10);
			}
		}
		if(djsl >=this.tidaiMtFifty[1]){
			if(this.type==108){
				CornerUtil.addCorner(this.btn_xunbao3,0,-10);
			}
			else{
				CornerUtil.addCorner(this.btn_xunbao3,0,-10);
			}
		}
	}

	__proto.changeTime=function(){
		var a=CommonUtil.formatDate(this.mgr.endTime-Mgr.curTime.serverTimer,26,false);
		var arr=a.split(":");
		var len=arr.length;
		for (var i=0;i < len;i++){
			if(this["ttime"+i]){
				this["ttime"+i].changeText(arr[i]);
			}
		}
	}

