var ZhanZhuangSkillItem1=(function(_super){
	function ZhanZhuangSkillItem1(){
		// public var skillVo:SkillVO;
		this.data=null;
		this._mgr=null;
		ZhanZhuangSkillItem1.__super.call(this);
		this._mgr=Mgr.zhanZhuangMgr;
	}

	__class(ZhanZhuangSkillItem1,'view.modules.zhanZhuang.ZhanZhuangSkillItem1',_super);
	var __proto=ZhanZhuangSkillItem1.prototype;
	__proto.refresh=function(){
		this.checkRed();
	}

	__proto.checkRed=function(){
		if(!this.data){
			CornerUtil.removeCorner(this);
			return
		}
		if(this._mgr.checkSuitActive(this.data)){
			this.skillIcon.gray=false;
			if(this._mgr.getCurEquipSuit()> 0){
				CornerUtil.removeCorner(this);
			}
			else{
				CornerUtil.addCorner(this);
			}
		}
		else{
			this.skillIcon.gray=true;
			CornerUtil.removeCorner(this);
		}
	}

	__getset(0,__proto,'dataSource',_super.prototype._$get_dataSource,function(value){
		if(!value)return;
		this.data=value;
		var type=this.data.getCfgData().id;
		var info=this.data.getValue("s_data");
		var lv=info&&info.level?info.level:1;
		var suitLvEle=this._mgr.getSuitLvEle(type,lv);
		if(!suitLvEle)return;
		var vo=SkillManager.ins.getData(suitLvEle.getCfgData().skill,false,lv);
		this.skillIcon.setSkillVo(vo);
		this.skillIcon.mouseEnabled=false;
		this.checkRed();
	});

	return ZhanZhuangSkillItem1;
})(ZhanZhuangSkillItem1UI)


