var NewItemRemindTip=(function(_super){
	function NewItemRemindTip(){
		this._curItem=null;
		this._item=null;
		this._itemType=0;
		this._cdTime=5;
		NewItemRemindTip.__super.call(this);
	}

	__class(NewItemRemindTip,'view.mainUI.subPanel.NewItemRemindTip',_super);
	var __proto=NewItemRemindTip.prototype;
	Laya.imps(__proto,{"com.xq.view.mainUI.subPanel.INewItemRemindTip":true})
	__proto.initialize=function(){
		laya.ui.Dialog.prototype.initialize.call(this);
	}

	__proto.startListener=function(){
		Laya.stage.on("resize",this,this.onResize);
		this.btnUse.on("click",this,this.onUse);
		this.btnClose.on("click",this,this.close);
	}

	__proto.stopListener=function(){
		Laya.stage.off("resize",this,this.onResize);
		this.btnUse.off("click",this,this.onUse);
		this.btnClose.off("click",this,this.close);
	}

	__proto.onOpened=function(){
		this.startListener();
		this.onResize();
		this.update(this._curItem);
	}

	__proto.onResize=function(){
		var w=Laya.stage.width;
		var h=Laya.stage.height;
		this.pos(w-220,h-550);
	}

	__proto.setData=function(vo){
		this._curItem=vo;
	}

	__proto.update=function(vo){
		if(!vo)return;
		var itemId=vo.itemId;
		if(!this._item){
			this._item=new ItemDisplayList();
			this.iconSp.addChild(this._item);
		}
		this._item.showItems([itemId+":"+vo.showCount],1);
		this._itemType=Mgr.item.checkItemType(itemId);
		if(this._itemType==1){
			var itemcfg=Model.daoJuModel.getDjCfg(itemId)
			this.itemName.changeText(itemcfg.name);
			var flag=itemcfg.usetip=="2";
			this.btnUse.label=flag?Lang.str(340):Lang.str(342);
			var isStartTimer=!flag;
		}
		else if(this._itemType==2){
			this.itemName.changeText(Model.equipCfg.getEquipName(itemId));
			this.btnUse.label=Lang.str(341);
			isStartTimer=true;
		}
		if(isStartTimer){
			this._cdTime=5;
			this.startTimer();
		}
	}

	__proto.startTimer=function(){
		Laya.timer.loop(1000,this,this.onCd);
	}

	__proto.onCd=function(){
		this._cdTime--;
		if(this._cdTime<=0){
			Laya.timer.clear(this,this.onCd);
			this.onUse();
			return;
		}
		this.btnUse.label=this._itemType==1?Lang.str(345)+this._cdTime+Lang.str(344):Lang.str(343)+this._cdTime+Lang.str(344);
	}

	__proto.onUse=function(){
		if(!this._curItem)return;
		if(this._itemType==1){
			var itemCfg=Model.daoJuModel.getDjCfg(this._curItem.itemId);
			if(!itemCfg){
				this.close();
				return;
			};
			var itemData=Mgr.newBagM.getItemDataByGuid(this._curItem.guid);
			if(!itemData){
				this.close();
				return;
			}
			if(itemCfg.skill=="10"){
				var obj=Mgr.item.getLiheMsg(this._curItem.itemId);
				if(obj && obj.chose=="1"){
					var bagVo=Mgr.bag.createItemVo(itemData.msg);
					bagVo.count=this._curItem.showCount;
					var tipChoose=UIMgr.ins.openView(TipChooseGiftPanel,2);
					tipChoose.showGift(obj,bagVo);
					}else{
					Mgr.newBagM.useBagItem(itemData.msg,true);
				}
			}
			else if(itemCfg.category==200){
				var taskGfitTip=UIMgr.ins.openView(TaskGiftTip,2);
				taskGfitTip.dataSource=this._curItem.itemId;
			}
			else{
				Mgr.newBagM.useBagItem(itemData.msg,true);
			}
		}
		else if(this._itemType==2){
			var curEquipData=Mgr.newBagM.getItemDataByGuid(this._curItem.guid);
			if(!curEquipData){
				this.close();
				return;
			};
			var equipCfg=Model.equipCfg.getEquipCfg(this._curItem.itemId);
			var equipType=equipCfg.type;
			var euqipPart=equipCfg.eqpart;
			if(equipType==1){
				if(euqipPart==7||euqipPart==8){
					UIMgr.ins.openView(RoleFrameView);
				}
				else{
					Mgr.equipPro.sendRoleDressEquipMsg(this._curItem.guid,curEquipData.msg.slotNum ,-euqipPart,Mgr.subPlayer.curGuid);
				}
			}
			else if(equipType==100||equipType==101||equipType==102||equipType==103||equipType==104){
				Mgr.yuanShenM.dressSingle(equipType-99,this._curItem.guid);
			}
			else if(equipType==200){
				Mgr.zhuoYueZhuangBeiM.dressSingle(1,this._curItem.guid);
			}
		}
		this.close();
	}

	__proto.onClosed=function(type){
		laya.ui.Dialog.prototype.onClosed.call(this);
		Laya.timer.clear(this,this.onCd);
		this.stopListener();
		if(this._curItem){
			this._curItem.recover();
			this._curItem=null;
		}
		Mgr.newItemRemindM.checkNext();
	}

	return NewItemRemindTip;
})(GetItemToUseTipUI)


