var TSBuyLevel=(function(_super){
	function TSBuyLevel(){
		this.ptItemList=null;
		this.jlItemList=null;
		TSBuyLevel.__super.call(this);
		this.bgView.setTxtName(Lang.str(456));
	}

	__class(TSBuyLevel,'view.modules.activity.tianShen.tianShenLing.TSBuyLevel',_super);
	var __proto=TSBuyLevel.prototype;
	__proto.initialize=function(){
		laya.ui.Dialog.prototype.initialize.call(this);
	}

	__proto.onClickBuy=function(){
		if(NetMgr.ins().roleVO.taiYu >=parseInt(this.costTxt.text)){
			var buyLv=parseInt(this.numInput.text);
			if(buyLv==0 || buyLv+Mgr.tslMgr.model.level > Mgr.tslMgr.maxBuyLv){
				Mgr.prompt.optionPrompt(Lang.str(457)+Mgr.tslMgr.maxBuyLv+Lang.str(251));
				return;
			}
			Mgr.tslAct.reqBuyLevel(buyLv);
		}
		else{
			if(Mgr.guide.isOpen("shouchonghaoli")){
				this.close();
				Mgr.kaiFuHDMgr.getSkip();
			}
			else{
				Mgr.prompt.optionPrompt(Lang.str(458));
			}
		}
	}

	__proto.onNumBtn=function(mark){
		var temp=parseInt(this.numInput.text);
		if(mark==0){
			temp-=1;
		}
		else{
			temp+=1;
		}
		if(temp <=0){
			temp=1
		}
		else if((temp+Mgr.tslMgr.model.level)> Mgr.tslMgr.maxBuyLv){
			temp=Mgr.tslMgr.maxBuyLv-Mgr.tslMgr.model.level;
			Mgr.prompt.optionPrompt(Lang.str(457)+Mgr.tslMgr.maxBuyLv+Lang.str(251));
		}
		this.numInput.text=temp.toString();
		this.showReward();
	}

	__proto.changeNum=function(){
		if(!this.numInput.text)
			this.numInput.text="1";
		else{
			var temp=parseInt(this.numInput.text);
			if(temp < 0){
				this.numInput.text="0"
			}
			else if((temp+Mgr.tslMgr.model.level)> Mgr.tslMgr.maxBuyLv){
				temp=Mgr.tslMgr.maxBuyLv-Mgr.tslMgr.model.level;
				this.numInput.text=temp.toString();
				Mgr.prompt.optionPrompt(Lang.str(457)+Mgr.tslMgr.maxBuyLv+Lang.str(251));
			}
		}
		this.showReward();
	}

	/**显示奖励*/
	__proto.showReward=function(){
		var curLv=Mgr.tslMgr.model.level;
		var maxLv=Mgr.tslMgr.maxBuyLv;
		if(curLv < maxLv){
			this.buyBtn.gray=false;
			if(! Mgr.tslMgr.model.hasGodToken){
				this.jhTxt.text=Lang.str(459);
			}
			else{
				this.jhTxt.text=Lang.str(460);
			}
		}
		else{
			this.numInput.text="0";
			this.buyBtn.gray=true;
			this.jhTxt.text=Lang.str(461)+maxLv+Lang.str(251);
		};
		var buyLv=parseInt(this.numInput.text);
		this.lvTxt1.text=Lang.str(400)+this.numInput.text+Lang.str(462)
		this.costTxt.text=(buyLv *Mgr.tslMgr.buycost).toString();
		this.ptItemList.showItems(Mgr.tslMgr.getRewardByLv(curLv+1,curLv+buyLv,false),6,100,100);
		this.ptItemList.showHorCenter(this.rewardPanel1.width);
		this.jlItemList.showItems(Mgr.tslMgr.getRewardByLv(curLv+1,curLv+buyLv,true),6,100,100);
		this.jlItemList.showHorCenter(this.rewardPanel2.width);
		this.tipTxt.text=Lang.str(400)+this.numInput.text+Lang.str(463)+(buyLv+curLv)+Lang.str(251);
	}

	__proto.onOpened=function(){
		if(!this.ptItemList){
			this.ptItemList=new ItemDisplayList();
			this.ptItemList.showHeight=this.rewardPanel1.height;
			this.rewardPanel1.addChild(this.ptItemList);
		};
		var maxLv=Mgr.tslMgr.maxBuyLv;
		if(!this.jlItemList){
			this.jlItemList=new ItemDisplayList();
			this.jlItemList.showHeight=this.rewardPanel2.height;
			this.rewardPanel2.addChild(this.jlItemList);
		}
		this.buyBtn.on("click",this,this.onClickBuy);
		this.reduceBtn.on("click",this,this.onNumBtn,[0]);
		this.addBtn.on("click",this,this.onNumBtn,[1]);
		this.numInput.on("input",this,this.changeNum);
		var buyLv=10;
		var curLv=Mgr.tslMgr.model.level;
		if(curLv+buyLv > maxLv){
			buyLv=maxLv-curLv;
			if(buyLv<0){
				buyLv=0;
			}
		}
		this.numInput.text=""+buyLv;
		this.numInput.restrict="0123456789";
		this.showReward();
		EventCenter.instance.on("UpdateTSLInfoTsEvent",this,this.showReward);
		EventCenter.instance.on("ONBuyTSLvSuccess",this,this.onBuySuccess);
	}

	__proto.onBuySuccess=function(){
		this.close();
	}

	__proto.onClosed=function(type){
		laya.ui.Dialog.prototype.onClosed.call(this)
		this.buyBtn.off("click",this,this.onNumBtn);
		this.addBtn.off("click",this,this.onNumBtn);
		this.numInput.off("input",this,this.changeNum);
		EventCenter.instance.off("UpdateTSLInfoTsEvent",this,this.showReward);
	}

	return TSBuyLevel;
})(TSBuyLevelUI)


