		var ele=this._mgr.getDataElement(selectIndex);
		if(!ele)return;
		var cfg=ele.getCfgData();
		var money=parseInt(cfg.money);
		var id=parseInt(cfg.id);
		var isLqReward=this._mgr.isGetReward(vo.getIds,id);
