var YaoQingView=(function(_super){
	function YaoQingView(){
		this.isGuide=false;
		YaoQingView.__super.call(this);
		CommonUtil.listSetScroll(this.list_invite,false);
		this.btn_friend.on("click",this,this.onClick);
		var ary=[this.btn_friend,this.btn_guild];
		this.btn_fujin.on("click",this,this.getRecommand);
		CommonUtil.addEvent(ary,"click",this,this.onClick);
		this.list_invite.visible=false;
		this.ba_panel.setTxtName(Lang.str(943));
	}

	__class(YaoQingView,'view.modules.fengshenlu.YaoQingView',_super);
	var __proto=YaoQingView.prototype;
	__proto.getRecommand=function(){
		this.updateYaoQing([]);
		this.isGuide=false;
		Mgr.fengshenluPro.sendGetRecommend();
	}

	__proto.onOpened=function(){
		this.updateYaoQing([]);
		EventCenter.instance.on("update_recommend",this,this.updateYaoQing);
		EventCenter.instance.on("update_guide_member",this,this.refreshGuideList);
		this.isGuide=false;
		Mgr.fengshenluPro.sendGetRecommend();
	}

	// btn_friend.skin="modules/common/btn_orange.png";
	__proto.updateYaoQing=function(msg){
		var recommendArr=[];
		var len=msg.length;
		var friendArr=Mgr.friendNMgr.getOnlineFriend();
		for (var i=0;i < len;i++){
			var info=new GuildMemberInfo();
			var recommendMsg=msg[i];
			info.isOnline=true;
			info.gender=recommendMsg.gender;
			info.level=recommendMsg.level;
			info.fightValue=recommendMsg.power;
			info.id=recommendMsg.roleId;
			info.name=recommendMsg.roleName;
			recommendArr.push(info);
		};
		var connectArr=recommendArr.concat(friendArr);
		var id=0;
		var id2=0;
		for(var j=0;j<connectArr.length;j++){
			id=connectArr[j].id||connectArr[j].roleId;
			for(var k=j+1;k<connectArr.length;k++){
				id2=connectArr[k].id||connectArr[k].roleId;
				if(id==id2){
					connectArr.splice(k,1);
					k--;
				}
			}
		}
		this.list_invite.array=connectArr;
		var isShow=connectArr.length==0;
		this.txt_none.visible=isShow;
		this.list_invite.visible=!isShow;
		this.txt_none.text=Lang.str(945);
		this.btn_friend.skin="modules/common/btn_black.png";
		this.btn_guild.skin="modules/common/btn_black.png";
		this.btn_fujin.skin="modules/common/btn_orange.png";
	}

	__proto.onClosed=function(type){
		EventCenter.instance.off("update_guide_member",this,this.refreshGuideList);
	}

	__proto.onClick=function(target){
		var isShow=false;
		switch(target){
			case this.btn_friend:{
					var friendArr=Mgr.friendNMgr.getOnlineFriend();
					this.list_invite.array=friendArr;
					isShow=friendArr.length==0;
					this.txt_none.visible=isShow;
					this.list_invite.visible=!isShow;
					this.txt_none.text=Lang.str(944);
					this.btn_friend.skin="modules/common/btn_orange.png";
					this.btn_guild.skin="modules/common/btn_black.png";
					this.btn_fujin.skin="modules/common/btn_black.png";
					break ;
				}
			case this.btn_guild:{
					this.isGuide=true;
					Mgr.guildPro.sendGetGuildInfo(0);
					break ;
				}
			}
	}

	__proto.refreshGuideList=function(){
		if(this.isGuide){
			var guildArr=[];
			var len=Mgr.guild.memberArr.length;
			console.log(NetMgr.ins().roleVO.guid)
			for (var i=0;i < len;i++){
				var data=Mgr.guild.memberArr [i];
				if(data.id !=NetMgr.ins().roleVO.guid && data.isOnline)
					guildArr.push(data);
			}
			this.list_invite.array=guildArr.sort(this.compare1);
			var isShow=guildArr.length==0;
			this.txt_none.visible=isShow;
			this.list_invite.visible=!isShow;
			this.txt_none.text=Lang.str(946);
			this.btn_guild.skin="modules/common/btn_orange.png";
			this.btn_friend.skin="modules/common/btn_black.png";
			this.btn_fujin.skin="modules/common/btn_black.png";
		}
	}

	__proto.compare1=function(vo1,vo2){
		if(vo1.fightValue < vo2.fightValue)
			return 1;
		else if(vo1.fightValue > vo2.fightValue)
		return-1;
		return 0;
	}

	return YaoQingView;
})(YaoQingViewUI)


