		this.txt_money2.changeText(this._bagCount+"/"+this._tenItemNeedCount);
		zhe=(this._tenItemNeedCount/(this._onceItemCount*10))*10;
		this.img_zhe2.visible=true;
		this.font_zhe2.visible=true;
