	__proto.updateLimitCount=function(storeItemVo){
		var count=storeItemVo.boughtCount;
		switch(storeItemVo.countLimitType){
			case 0:
				this.xiangou.text="";
				break ;
			case 1:
				this.xiangou.text=Lang.str(1225)+count+"/"+storeItemVo.maxCount;
				break ;
			case 2:
				this.xiangou.text=Lang.str(1571)+count+"/"+storeItemVo.maxCount;
				break ;
			case 3:
				this.xiangou.text=Lang.str(1572)+count+"/"+storeItemVo.maxCount;
				break ;
			}
		if(storeItemVo.countLimitType==0){
			this.curBuyLimitNum=-1;
			}else{
			this.curBuyLimitNum=storeItemVo.maxCount-count;
		};
		var myMoney=Mgr.moneyMgr.getMoneyByType(this.storeItemVO.moneyType);
		var goldBuyNum=999;
		if(goldBuyNum > this.curBuyLimitNum){
			if(this.curBuyLimitNum==-1){
				this.mayBuyNum=goldBuyNum;
				}else{
				this.mayBuyNum=this.curBuyLimitNum;
			}
			}else{
			this.mayBuyNum=goldBuyNum;
		}
	}

