			if (objVO==null){
				console.error("道具id：“"+id+"”不存在");
				return;
			}
			if(needCount)objVO.count=1;
			v=PoolUtil.getItemByIClass("Item",com.xq.view.modules.bag.IBagItemFactoryView);
