	/**获取装备总战力*/
	__proto.getEquipFv=function(equipVo){
		this.txt_allStore.text=""+this.getAllScore(equipVo);
		this.txt_equipScore.text=""+equipVo.attrScore;
		var curEquipData=Mgr.equip.getItemVo(1,equipVo.partPos);
		if(!curEquipData)return;
		var curEquip=Mgr.equip.createEquipVO(curEquipData.msg);
		this.txt_otherName.text=this.equipVO.cfgItem.itemlevel+Lang.str(374)+ColorTypeEnum.getZi(this.equipVO.rareLv)+this.equipVO.cfgItem.star+Lang.str(1643);
		this.txt_baseDif.x=this.txt_compositeDif.x=26;
		this.img_base.y=5;
		this.img_composite.y=31;
		if(curEquip){
			var equipScoreDif=curEquip.attrScore-equipVo.attrScore;
			if(equipScoreDif > 0){
				this.img_base.skin="modules/common/hint1.png";
				}else if(equipScoreDif==0){
				this.img_base.skin="modules/common/hintLine.png";
				this.txt_baseDif.x=26+35;
				this.img_base.y=3;
				}else{
				this.img_base.skin="modules/common/hint2.png";
			}
			this.txt_baseDif.text=Math.abs(equipScoreDif)+"";
			equipScoreDif=this.getAllScore(curEquip)-this.getAllScore(equipVo);
			if(equipScoreDif > 0){
				this.img_composite.skin="modules/common/hint1.png";
				}else if(equipScoreDif==0){
				this.img_composite.skin="modules/common/hintLine.png";
				this.txt_compositeDif.x=26+35;
				this.img_composite.y=29;
				}else{
				this.img_composite.skin="modules/common/hint2.png";
			}
			this.txt_compositeDif.text=Math.abs(equipScoreDif)+"";
			this.txt_ownName.text=curEquip.cfgItem.itemlevel+Lang.str(374)+ColorTypeEnum.getZi(curEquip.rareLv)+curEquip.cfgItem.star+Lang.str(1643);
			this.txt_ownName.x=420;
			}else{
			this.img_composite.skin="modules/common/hint2.png";
			this.img_base.skin="modules/common/hint2.png";
			this.txt_baseDif.text=equipVo.attrScore+"";
			this.txt_compositeDif.text=this.getAllScore(equipVo)+"";
			this.txt_ownName.text=Lang.str(428);
			this.txt_ownName.x=314+15;
		}
	}

	__proto.getAllScore=function(equipVo){
		var equipFv=0
		if(equipVo.gemArr){
			var len=equipVo.gemArr.length;
			for (var i=0;i < len;i++){
				var tempId=equipVo.gemArr[i].templateId
				if(tempId !=""){
					var attrVO=Mgr.gemMgr.getGemAttrData(tempId);
					equipFv+=parseInt(attrVO.attrFV);
				}
			}
		}
		equipFv+=AttributeTypeEnum.getZdlByAttrMsg(equipVo.strengthAttrs);
		equipFv+=AttributeTypeEnum.getZdlByAttrMsg(equipVo.starAttrs);
		equipFv+=AttributeTypeEnum.getZdlByAttrMsg(this.getEquipWashAttr(equipVo.washArr));
		return equipFv+equipVo.totalScore;
	}

	__proto.getEquipWashAttr=function(washArr){
		if(!washArr)return null;
		var washAttrArr=[];
		var len=washArr.length;
		for (var i=0;i < len;i++){
			var attrCfgMsg=Mgr.equipWashMgr.washAttrCfg.getItemByField("ID",washArr[i].templateId.toString());
			var attrObj=AttributeTypeEnum.getAttrObj(attrCfgMsg.type);
			var attributeMsg=new AttributeMsg();
			attributeMsg.attrId=parseInt(attrObj.id);
			attributeMsg.attrValue=parseFloat(washArr[i].attributeVal);
			washAttrArr.push(attributeMsg);
		}
		return washAttrArr;
	}

	__proto.checkWash=function(equipVO,y){
		if (equipVO.whichPanel==11 ||
			equipVO.whichPanel==1 ||
		equipVO.whichPanel==2 ||
		equipVO.whichPanel==3 ||
		equipVO.whichPanel==6 ||
		equipVO.whichPanel==5||
		equipVO.whichPanel==8){
			var washVo=Mgr.equipWashMgr.getWashVo(equipVO.partPos);
			if (equipVO.washArr && equipVO.washArr.length > 0 || (washVo &&washVo.info && washVo.info.xiLianAttributeMsgList.length > 0)){
				var v=new EquipTipWashView();
				this.contentVBox.addChild(v);
				v.dataSource=equipVO;
				v.y=y;
			}
		}
	}

