//class view.modules.tips.TipChooseGiftPanel extends ui.modules.tips.TipChooseGiftPanelUI
var TipChooseGiftPanel=(function(_super){
	function TipChooseGiftPanel(){
		this.canChooseNum=1;
		this.rewardItems=null;
		this.chooseIndexArr=null;
		this.curBagItemVo=null;
		this._selectNum=1;
		this._maxNum=0;
		this._gifts=null;
		TipChooseGiftPanel.__super.call(this);
		this.itemList.vScrollBarSkin="";
		this.itemList.selectEnable=true;
		this.itemList.scrollBar.elasticBackTime=300;
		this.itemList.scrollBar.elasticDistance=100;
		this.itemList.renderHandler=Handler.create(this,this.onRenderChange,null,false);
		this.itemList.on("click",this ,this.onSelected);
		this.chooseIndexArr=[];
		this.btnSure.on("click" ,this ,this.onBtnOk);
		this.btnMinus.on("click",this,this.onMinus);
		this.btnAdd.on("click",this,this.onAdd);
		this.tipSlider.changeHandler=new Handler(this,this.onChange);
	}

	__class(TipChooseGiftPanel,'view.modules.tips.TipChooseGiftPanel',_super);
	var __proto=TipChooseGiftPanel.prototype;
	__proto.onOpened=function(){
		this.bgV.setTxtName(Lang.str(1665));
	}

	__proto.onBtnOk=function(){
		if(this.chooseIndexArr.length==this.canChooseNum){
			for(var i=0;i<this._selectNum;i++){
				var vo=this.curBagItemVo;
				Mgr.item.sendChooseGift(vo.guid ,this.chooseIndexArr);
			}
			this.close();
		}
		else{
			Mgr.prompt.optionPrompt(Lang.str(1666)+this.canChooseNum+Lang.str(1667));
		}
	}

	__proto.onSelected=function(e){
		if(e.target.name!=""){
			var index=this.itemList.selectedIndex;
			if(index!=-1){
				var d=this.rewardItems[index];
				if(d){
					if(d.selected){
						this.chooseIndexArr.splice(this.chooseIndexArr.indexOf(index),1);
						d.selected=false;
					}
					else{
						if(this.chooseIndexArr.length==this.canChooseNum){
							var unChoose=this.chooseIndexArr.shift();
							var data=this.rewardItems[unChoose];
							if(data){
								data.selected=false;
							}
						}
						this.chooseIndexArr.push(index);
						d.selected=true;
					}
					this.itemList.refresh();
					this.updateChooseNum();
				}
			}
		}
	}

	__proto.onChange=function(value){
		this.txt_num.text=value.toString();
		this._selectNum=value;
	}

	__proto.onMinus=function(){
		if (this._selectNum <=1){
			return;
		}
		this._selectNum--;
		this.txt_num.text=this._selectNum.toString();
		this.tipSlider.value=this._selectNum;
	}

	__proto.onAdd=function(){
		if (this._selectNum >=this._maxNum){
			return;
		}
		this._selectNum++;
		this.txt_num.text=this._selectNum.toString();
		this.tipSlider.value=this._selectNum;
	}

	__proto.onRenderChange=function(cell,index){
		if(this.rewardItems){
			var data=this.rewardItems[index];
			if(data){
				var bagItem=cell.getChildByName("icon");
				bagItem.dataSource=data.itemVo;
				var ck=cell.getChildByName("selectBar");
				ck.mouseEnabled=false;
				ck.selected=data.selected;
				var txt=cell.getChildByName("name");
				txt.text=data.itemVo?data.itemVo.goodName:"";
			}
		}
	}

	/**
	*显示礼盒
	**/
	__proto.showGift=function(liHeCfg,bagItemVO){
		this.canChooseNum=liHeCfg.num;
		this.txt_tip1.text=Lang.str(1668);
		this.descLbl.text=this.canChooseNum+Lang.str(690);
		this.txt_tip2.text=Lang.str(1669);
		this.box_tips.refresh();
		this.curBagItemVo=bagItemVO;
		this.txt_name.text=this.curBagItemVo.goodName;
		this._maxNum=this.curBagItemVo.count;
		this.tipSlider.min=1;
		this.tipSlider.max=this._maxNum;
		this.tipSlider.value=this._maxNum;
		this.txt_num.text=this.tipSlider.value+"";
		this.chooseIndexArr.length=0;
		this.itemList.selectedIndex=-1;
		var things=liHeCfg.things.split(";");
		this.rewardItems=[];
		for (var i=0;i < things.length;i++){
			var rewardItem={};
			var rewardInfo=things[i].split(":");
			rewardItem.itemVo=Mgr.item.getItemVO(rewardInfo[0],rewardInfo[2],rewardInfo[1]);
			rewardItem.index=i;
			rewardItem.selected=false;
			this.rewardItems.push(rewardItem);
		}
		this.itemList.dataSource=this.rewardItems;
		this.updateChooseNum();
	}

	__proto.updateChooseNum=function(){
		this.lblOption.text=Lang.str(1670)+this.chooseIndexArr.length+"/"+this.canChooseNum+Lang.str(1671);
	}

	return TipChooseGiftPanel;
})(TipChooseGiftPanelUI)


