	__proto.onListSelect=function(index){
		if(index==-1)return;
		this._curSelectIndex=index;
		var len=this._chatItems.length;
		var cellLen=this.list.length;
		var cell
		for(var j=0;j<cellLen;j++){
			cell=this.list.getCell(j);
			if(cell){
				index==j?cell.item.selected=true:cell.item.selected=false;
			}
		}
		for(var i=0;i<len;i++){
			this._chatItems[i].dispose();
		}
		this._chatItems.length=0;
		this._vo=this.list.selectedItem;
		if(this._vo){
			this.updateChat();
		}
	}

	__proto.updateChat=function(targetId){
		(targetId===void 0)&& (targetId=0);
		if(!this._vo||(targetId&&this._vo.roleId!=targetId))return;
		this._charArr=Mgr.friendNMgr.getChatById(this._vo.roleId);
		if(!this._charArr)return;
		var item;
		var len=this._charArr.length;
		if(this._chatItems.length==0){
			for(var i=0;i<len;i++){
				item=FriendChatItem.getItem();
				item.setData(this._charArr[i]);
				this.v_list.addChild(item);
				this._chatItems.push(item);
			}
			}else{
			item=FriendChatItem.getItem();
			item.setData(this._charArr[len-1]);
			item.y=this.v_list.height;
			this.v_list.addChild(item);
			this._chatItems.push(item);
		}
		this.v_list.refresh();
		Laya.timer.once(50,this,this.refreshSlPanel);
	}

	__proto.refreshSlPanel=function(){
		this.panel.refresh();
		this.panel.scrollTo(0,this.v_list.height);
	}

	__proto.startTimer=function(){
		this._time=Mgr.friendNMgr.time-Mgr.curTime.serverTimer;
		if(this._time>0){
			this.btn_send.label=Lang.str(313)+CommonUtil.formatDate(this._time,17);
			Laya.timer.loop(1000,this,this.onCd);
			this.ifCd=true;
		}
		else{
			this.ifCd=false;
			this.btn_send.label=Lang.str(313);
		}
	}

	__proto.onCd=function(){
		this._time-=1000;
		if(this._time<=0){
			this.btn_send.label=Lang.str(313);
			Laya.timer.clear(this,this.onCd);
			this.ifCd=false;
			return;
		}
		this.btn_send.label=Lang.str(313)+CommonUtil.formatDate(this._time,17);
	}

	__proto.close=function(type,showEffect){
		(showEffect===void 0)&& (showEffect=true);
		if(this.biaoqingView)
			this.biaoqingView.removeSelf();
		this.isBiaoqing=false;
		this.isBag=false;
		this.itemVo=null;
		laya.ui.AsynDialog.prototype.close.call(this,type,false);
	}

	__proto.onClosed=function(type){
		this.stopListener();
		this.tempStr="";
		this.tab_tab.selectedIndex=-1;
		this.lastSelect=0;
		Mgr.chat.chatSelect=0;
		this.clearChatItemAni();
		InputMgr.getInstance().isChat=false;
		var len=this._chatItems.length;
		for(var i=0;i<len;i++){
			this._chatItems[i].dispose();
		}
		this._chatItems.length=0;
		this._limitCode=0;
	}

	/**
	*@private
	*/
	/**当前选中的标签索引*/
	__getset(0,__proto,'curIndex',function(){
		return this._curIndex;
		},function(value){
		this._curIndex=value;
	});

	__getset(0,__proto,'hi',function(){
		return this._hi;
		},function(value){
		this._hi=value;
	});

