		if(!this.bigRewardItems){
			this.bigRewardItems=new ItemDisplayList();
			this.sp_reward.addChild(this.bigRewardItems);
		}
		this.bigRewardItems.showItems(obj.rewardItem1,5,60,60,0.6,true,true,0,false,false);
		this.bigRewardItems.showHorCenter(this.sp_reward.width);
